const DEATH_VULGARITIES = [
  "FUCK THIS WORLD", "I'LL SEE YOU IN HELL", "SHIT", "DAMN IT ALL",
  "WHO'S GONNA SPOT ME NOW?", "CREATINE CRASH", "OVERTRAINED",
  "CREATINE WITHDRAWAL", "SYSTEM FAILURE... NEED PROTEIN", "FUCK THE WEIGHTS... I'M OUT", 
  "HEART EXPLODED... WORTH IT", "BURY ME IN THE SQUAT RACK", "NO REPS LEFT", 
  "TOTAL MUSCLE FAILURE", "GAINS RESET TO ZERO", "TELL MY SPOTTER... I LOVE HIM", 
  "DROPPED THE BAR ON MY NECK", "SHITTY RECOVERY... GOODBYE", "GYM CLOSED... FOREVER"
];

const INTRO_QUOTES: Record<string, string> = {
  'Victor Volcano': "Hell hath no fury like roid rage.",
  'Artie Avalanche': "What killed the dinosaurs? The ice age!",
  'Hector Hurricane': "Katrina's got nothing on my wrath.",
  'Ernie Earthquake': "I'D BE QUAKING IN MY boots IF I WERE YOU."
};

const GORE_COLORS = ['#8B0000', '#FF0000', '#B22222', '#7C0A02', '#5A0000', '#FF1111'];
const FLESH_COLORS = ['#FF8A80', '#FF5252', '#FF1744', '#D50000', '#C62828']; // Meaty shades instead of skin tones
const ROCK_COLORS = ['#4E342E', '#3E2723', '#212121', '#757575'];
const GLASS_COLORS = ['#ADD8E6', '#F0F8FF', '#FFFFFF', '#B0C4DE'];
const FIRE_COLORS = ['#FF4500', '#FF8C00', '#FFA500', '#FFD700', '#FF0000'];
const WATER_COLORS = ['#00BFFF', '#1E90FF', '#4169E1', '#0000FF', '#ADD8E6'];
const STEAM_COLORS = ['#FFFFFF', '#E0F7FA', '#B2EBF2', '#E1F5FE'];
const POOP_COLORS = ['#5D4037', '#3E2723', '#4E342E', '#795548', '#212121'];

type VulgarityType = 'gun_kill' | 'boulder_kill' | 'shotgun_kill' | 'flamethrower_kill' | 'tsunami_kill' | 'hurt' | 'death' | 'charge_kill' | 'uppercut_kill';

interface Volcano {
  pos: Vector2;
  life: number;
  type: 'wall' | 'ground';
}

interface SteamExplosion {
  pos: Vector2;
  life: number;
  radius: number;
}

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, specialCharges: number, specialChargeTimer: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => void;
  onBossEncounter: () => void;
  onBossTransition: () => void;
  onBossDefeated: (stageId: string) => void;
  onBossDeath: () => void;
  onGameOver: (victory: boolean) => void;
  onIntroComplete: () => void;
  onTogglePause: () => void;
  currentWeapon: WeaponType;
  initialAmmo: Record<WeaponType, number>;
  invincibilityEnabled: boolean;
  infiniteAmmoEnabled: boolean;
  jumpToBossEnabled: boolean;
  bossTauntText: string;
}

const BOSS_DOOR_X = 7200;
const DOOR_WIDTH = 40;

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  status, stageId, onPlayerUpdate, onBossEncounter, onBossTransition, 
  onBossDefeated, onBossDeath, onGameOver, onIntroComplete, onTogglePause, 
  currentWeapon, initialAmmo, invincibilityEnabled, infiniteAmmoEnabled, jumpToBossEnabled,
  bossTauntText
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isUppercutting: false,
      isDucking: false,
      specialCharges: MAX_SPECIAL_CHARGES,
      specialChargeTimer: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0,
      pushbackTimer: 0,
      killSatisfactionTimer: 0,
      hasUsedAirMove: false,
      jumpInputReleased: true,
      chargeInputReleased: true,
      currentWeapon: 'GUN',
      availableWeapons: ['GUN'],
      weaponAmmo: { ...initialAmmo }
    } as Player & { killSatisfactionTimer: number },
    enemies: [] as (Enemy & { bossState?: 'idle' | 'jumping' | 'attacking' | 'hurricane' | 'telegraphing' | 'stunned_drop', stateTimer?: number, jumpCount?: number, pauseTimer?: number, isGroundedBoss?: boolean, sideTimer?: number, said75?: boolean, said50?: boolean, said25?: boolean })[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as (Particle & { isWater?: boolean })[],
    damageNumbers: [] as DamageNumber[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    playerLastVulgarity: "",
    playerVulgarityTimer: 0,
    bossLastVulgarity: "",
    bossVulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryString: "",
    deathString: "",
    deathTimer: 0,
    postVictoryTimer: 0,
    introTimer: 0,
    bossExplosionTimer: 0,
    bossExplosionPos: { x: 0, y: 0 },
    tsunamiX: -1,
    tsunamiStartX: 0,
    tsunamiActive: false,
    tsunamiDir: 1,
    bossVolcanoes: [] as Volcano[],
    bossVolcanoTelegraphs: [] as Volcano[],
    bossPoopTelegraphs: [] as { pos: Vector2, life: number, spawnX: number }[],
    bossSteamExplosions: [] as SteamExplosion[],
    bossTsunamiSide: 0 as number,
    bossTsunamiTimer: 0,
    victorWallSide: 0 as number, // 0 for left, 1 for right
    ernieVibrationTimer: 0,
    playerStunTimer: 0,
    screenShakeTimer: 0,
    shouldSyncWeapon: false
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  useEffect(() => {
    gameStateRef.current.player.currentWeapon = currentWeapon;
  }, [currentWeapon]);

  useEffect(() => {
    if (gameStateRef.current.deathTimer <= 0) {
      gameStateRef.current.player.weaponAmmo = { ...initialAmmo };
    }
  }, [initialAmmo]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const k = e.key.toLowerCase();
      const c = e.code.toLowerCase();
      keys.current[k] = true;
      keys.current[c] = true;
    };
    const handleKeyUp = (e: KeyboardEvent) => {
      const k = e.key.toLowerCase();
      const c = e.code.toLowerCase();
      keys.current[k] = false;
      keys.current[c] = false;
    };
    const handleMouseDown = () => mouse.current.down = true;
    const handleMouseUp = () => mouse.current.down = false;
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
      if (audioCtxRef.current) audioCtxRef.current.close();
    };
  }, []);

  const spawnDamageNumber = (pos: Vector2, value: number, isCritical: boolean = false) => {
    const state = gameStateRef.current;
    state.damageNumbers.push({
      id: `dmg-${Date.now()}-${Math.random()}`,
      value: Math.floor(value),
      pos: { ...pos },
      vel: { x: (Math.random() - 0.5) * 4, y: -4 - Math.random() * 2 },
      life: 45,
      maxLife: 45,
      isCritical
    });
  };

  const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15, isGlass: boolean = false, isBossGore: boolean = false) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      if (state.particles.length > 2500) break; 
      state.particles.push({
        pos: { ...pos },
        vel: { 
          x: baseVelX + (Math.random() - 0.5) * spread, 
          y: (Math.random() - 0.5) * spread 
        },
        life: isGlass ? 150 + Math.random() * 200 : 20 + Math.random() * 80,
        color: color,
        size: i % 3 === 0 ? 1 + Math.random() * 4 : 2 + Math.random() * 12,
        isGlass,
        isBossGore
      });
    }
  };

  const spawnSteamExplosionParticles = (pos: Vector2, count: number = 30) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      state.particles.push({
        pos: { ...pos },
        vel: { x: (Math.random() - 0.5) * 12, y: (Math.random() - 0.5) * 12 - 4 },
        life: 35 + Math.random() * 25,
        color: STEAM_COLORS[Math.floor(Math.random() * STEAM_COLORS.length)],
        size: 10 + Math.random() * 18
      });
    }
  };

  const spawnPoopExplosion = (pos: Vector2, count: number = 20) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      const isCorn = Math.random() < 0.35;
      const color = isCorn ? '#FFEB3B' : POOP_COLORS[Math.floor(Math.random() * POOP_COLORS.length)];
      state.particles.push({
        pos: { ...pos },
        vel: { x: (Math.random() - 0.5) * 16, y: (Math.random() - 0.5) * 16 },
        life: 50 + Math.random() * 60,
        color: color,
        size: isCorn ? 4 + Math.random() * 3 : 6 + Math.random() * 8
      });
    }
  };

  const spawnBoulderShrapnel = (pos: Vector2, count: number, direction: number) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      const ang = (Math.random() - 0.5) * Math.PI;
      const speed = 12 + Math.random() * 18; 
      state.projectiles.push({
        id: `shrap-${Date.now()}-${i}`,
        pos: { ...pos },
        vel: { x: (direction * -1) * Math.cos(ang) * speed, y: Math.sin(ang) * speed - 8 },
        width: 12, height: 12, health: 1, maxHealth: 1, type: 'projectile',
        damage: 60, owner: 'player', life: 45, isShrapnel: true
      });
    }
  };

  const spawnIceFizzle = (pos: Vector2) => {
    const state = gameStateRef.current;
    const fizzleColors = ['#FFFFFF', '#E0FFFF', '#AFEEEE', '#B0E0E6'];
    for (let i = 0; i < 12; i++) {
      state.particles.push({
        pos: { x: pos.x + Math.random() * 14 - 7, y: pos.y + Math.random() * 14 - 7 },
        vel: { x: (Math.random() - 0.5) * 2.0, y: -Math.random() * 2.0 - 0.5 },
        life: 25 + Math.random() * 35,
        color: fizzleColors[Math.floor(Math.random() * fizzleColors.length)],
        size: 2 + Math.random() * 6
      });
    }
  };

  const spawnDeathShower = (pos: Vector2, facing: number = 0, multiplier: number = 1, isBossDeath: boolean = false) => {
    FLESH_COLORS.forEach(c => spawnExplosion(pos, c, Math.ceil(8 * multiplier), facing * 18, 25, false, isBossDeath));
    GORE_COLORS.forEach(c => spawnExplosion(pos, c, Math.ceil(12 * multiplier), facing * 22, 35, false, isBossDeath));
    if (!isBossDeath) {
      spawnExplosion(pos, '#FF4500', Math.ceil(10 * multiplier), facing * 12, 40);
      spawnExplosion(pos, '#FFFF00', Math.ceil(5 * multiplier), facing * 8, 30);
    }
  };

  const spawnRockShatter = (pos: Vector2) => {
    ROCK_COLORS.forEach(c => spawnExplosion(pos, c, 8, 0, 20));
  };

  const spawnGlassShatter = (pos: Vector2) => {
    const ctx = canvasRef.current?.getContext('2d');
    if (!ctx) return;
    GLASS_COLORS.forEach(c => spawnExplosion(pos, c, 5, 0, 25, true));
    playGlassShatterSound();
  };

  const triggerBossDeath = (boss: Enemy, playerFacing: number, wasWeakness: boolean) => {
    const state = gameStateRef.current;
    if (state.bossExplosionTimer > 0) return;
    const pos = { x: boss.pos.x + boss.width / 2, y: boss.pos.y + boss.height / 2 };

    if (stageId && BOSS_THRESHOLDS[stageId]) {
      speakAsBoss(stageId, BOSS_THRESHOLDS[stageId][0]);
    }

    // IMMEDIATELY remove persistent hazards when boss dies
    state.bossVolcanoes = [];
    state.bossVolcanoTelegraphs = [];
    state.bossPoopTelegraphs = [];
    state.bossSteamExplosions = [];
    state.ernieVibrationTimer = 0;

    // IMMEDIATELY clear all active projectiles (player and enemy)
    state.projectiles = [];

    // Stop Tsunami attack immediately
    state.tsunamiActive = false;
    state.tsunamiX = -1;

    if (wasWeakness) {
      state.bossExplosionTimer = 180; 
      state.bossExplosionPos = pos;
      spawnDeathShower(state.bossExplosionPos, playerFacing, 25, true); 
    } else {
      spawnDeathShower(pos, playerFacing, 6, true);
      onBossDeath(); 
      state.victoryString = "V"; 
      state.postVictoryTimer = 0;
    }
    state.player.killSatisfactionTimer = 120;
    state.arenaLocked = false;

    const wpn = state.player.currentWeapon;
    let cat: VulgarityType = 'gun_kill';
    if (wpn === 'BOULDER') cat = 'boulder_kill';
    else if (wpn === 'SHOTGUN') cat = 'shotgun_kill';
    else if (wpn === 'FLAMETHROWER') cat = 'flamethrower_kill';
    else if (wpn === 'TSUNAMI') cat = 'tsunami_kill';
    speakVulgarity(cat);
  };

  const speakAsBoss = (bossId: string, text: string) => {
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);
      switch (bossId) {
        case 'Artie Avalanche': utterance.pitch = 1.6; utterance.rate = 0.85; break;
        case 'Victor Volcano': utterance.pitch = 0.7; utterance.rate = 0.85; break;
        case 'Ernie Earthquake': utterance.pitch = 0.1; utterance.rate = 0.55; break;
        case 'Hector Hurricane': utterance.pitch = 1.2; utterance.rate = 1.5; break;
        default: utterance.pitch = 1.0; utterance.rate = 1.0;
      }
      utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
      gameStateRef.current.bossLastVulgarity = text;
      gameStateRef.current.bossVulgarityTimer = 150;
    }
  };

  const speakVulgarity = (category: VulgarityType) => {
    const state = gameStateRef.current;

    if (!('speechSynthesis' in window)) return;
    if (window.speechSynthesis.speaking) return;
    if (state.voiceLineCooldown > 0) return;

    let pool = GUN_KILL_VULGARITIES;
    if (category === 'hurt') {
      if (state.arenaLocked && stageId && BOSS_HURT_VULGARITIES[stageId]) {
        pool = BOSS_HURT_VULGARITIES[stageId];
      } else {
        pool = HURT_VULGARITIES;
      }
    }
    if (category === 'death') pool = DEATH_VULGARITIES;
    if (category === 'charge_kill') pool = CHARGE_KILL_VULGARITIES;
    if (category === 'uppercut_kill') pool = UPPERCUT_KILL_VULGARITIES;
    if (category === 'boulder_kill') pool = BOULDER_KILL_VULGARITIES;
    if (category === 'shotgun_kill') pool = SHOTGUN_KILL_VULGARITIES;
    if (category === 'flamethrower_kill') pool = FLAMETHROWER_KILL_VULGARITIES;
    if (category === 'tsunami_kill') pool = TSUNAMI_KILL_VULGARITIES;

    const text = pool[Math.floor(Math.random() * pool.length)];
    state.playerLastVulgarity = text;
    state.playerVulgarityTimer = 120;

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.pitch = 0.1; 
    utterance.rate = 1.2; 
    utterance.volume = 1.0;

    utterance.onend = () => {
      state.voiceLineCooldown = 60;
    };
    utterance.onerror = () => {
      state.voiceLineCooldown = 60;
    };

    window.speechSynthesis.speak(utterance);
  };

  const playGlassShatterSound = () => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      for(let i=0; i<12; i++) {
        const osc = ctx.createOscillator(); const gain = ctx.createGain();
        osc.type = i % 2 === 0 ? 'sine' : 'sawtooth';
        osc.frequency.setValueAtTime(1200 + Math.random() * 5000, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.3);
        gain.gain.setValueAtTime(0.1, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3);
        osc.connect(gain); gain.connect(ctx.destination);
        osc.start(); osc.stop(ctx.currentTime + 0.3);
      }
    } catch (e) {}
  };

  const playGunSound = (type: 'gun' | 'ice' | 'flame' | 'tsunami' = 'gun') => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator(); const gain = ctx.createGain();
      if (type === 'gun') {
        osc.type = 'sawtooth'; osc.frequency.setValueAtTime(150, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(40, ctx.currentTime + 0.1);
        gain.gain.setValueAtTime(0.05, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      } else if (type === 'ice') {
        osc.type = 'sine'; osc.frequency.setValueAtTime(800, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(1200, ctx.currentTime + 0.1);
        gain.gain.setValueAtTime(0.08, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.15);
      } else if (type === 'flame') {
        osc.type = 'triangle'; osc.frequency.setValueAtTime(40 + Math.random() * 40, ctx.currentTime);
        osc.frequency.linearRampToValueAtTime(120, ctx.currentTime + 0.05);
        gain.gain.setValueAtTime(0.03, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.05);
      } else if (type === 'tsunami') {
          const bufferSize = ctx.sampleRate * 0.5; 
          const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
          const data = buffer.getChannelData(0);
          for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
          const noise = ctx.createBufferSource();
          noise.buffer = buffer;
          const filter = ctx.createBiquadFilter();
          filter.type = 'lowpass'; filter.frequency.setValueAtTime(1000, ctx.currentTime); filter.frequency.exponentialRampToValueAtTime(100, ctx.currentTime + 0.5);
          noise.connect(filter); filter.connect(ctx.destination);
          noise.start();
          return;
      }
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  };

  const speakIntroLine = (id: string | null) => {
    if (!id || !INTRO_QUOTES[id]) return;
    if ('speechSynthesis' in window) {
      if (window.speechSynthesis.speaking) return;

      const utterance = new SpeechSynthesisUtterance(INTRO_QUOTES[id]);
      utterance.pitch = 0.1; utterance.rate = 1.0; utterance.volume = 1.0;

      utterance.onend = () => {
        gameStateRef.current.voiceLineCooldown = 60;
      };

      window.speechSynthesis.speak(utterance);
      gameStateRef.current.playerLastVulgarity = INTRO_QUOTES[id];
      gameStateRef.current.playerVulgarityTimer = 180;
    }
  };

  const spawnPickup = (pos: Vector2) => {
    const r = Math.random();
    if (r < 0.6) {
        const pr = Math.random();
        let type: PickupType;
        if (pr < 0.25) type = 'small_health';
        else if (pr < 0.35) type = 'large_health';
        else if (pr < 0.8) type = 'small_ammo';
        else type = 'large_ammo';
        gameStateRef.current.pickups.push({
            id: `pickup-${Date.now()}-${Math.random()}`,
            pos: { ...pos },
            vel: { x: (Math.random() - 0.5) * 4, y: -5 },
            width: 20,
            height: 20,
            type,
            life: 600
        });
    }
  };

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; const doorX = BOSS_DOOR_X;
    state.arenaLocked = false;
    state.doorState = 'closed';
    state.doorOpenAmount = 0;

    // Reset all boss-specific hazards from memory
    state.bossVolcanoes = [];
    state.bossVolcanoTelegraphs = [];
    state.bossPoopTelegraphs = [];
    state.bossSteamExplosions = [];
    state.victorWallSide = 0;
    state.ernieVibrationTimer = 0;
    state.playerStunTimer = 0;
    state.tsunamiActive = false;

    const addPickupOnPlatform = (block: { x: number, y: number, w: number, h: number }) => {
        const type: PickupType = Math.random() > 0.5 ? 'small_health' : 'small_ammo';
        state.pickups.push({
            id: `static-pickup-${Date.now()}-${Math.random()}`,
            pos: { x: block.x + block.w / 2 - 10, y: block.y - 25 },
            vel: { x: 0, y: 0 },
            width: 20,
            height: 20,
            type,
            life: 20000 
        });
    };

    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: DOOR_WIDTH, h: 150, type: 'door' },
      { x: doorX, y: -1000, w: DOOR_WIDTH, h: 1400, type: 'wall' },
      { x: doorX, y: 0, w: stageWidth - doorX, h: 100, type: 'wall' },
      { x: 7960, y: 100, w: 40, h: 500, type: 'wall' }
    ];

    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            const p1 = { x: i, y: 450, w: 150, h: 20, type: 'platform' };
            const p2 = { x: i + 200, y: 320, w: 150, h: 20, type: 'platform' };
            const p3 = { x: i + 400, y: 190, w: 150, h: 20, type: 'platform' };
            state.blocks.push(p1, p2, p3);
            if (Math.random() > 0.4) addPickupOnPlatform(p2);
            if (Math.random() > 0.6) addPickupOnPlatform(p3);
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            const p1 = { x: i, y: 380, w: 300, h: 20, type: 'platform' };
            const p2 = { x: i + 400, y: 250, w: 200, h: 20, type: 'platform' };
            state.blocks.push(p1, p2);
            if (Math.random() > 0.3) addPickupOnPlatform(p1);
            if (Math.random() > 0.3) addPickupOnPlatform(p2);
        }
        for (let x = 1200; x < doorX; x += 1800) { state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); }
    } else {
        for (let i = 600; i < doorX; i += 600) { 
            const p = { x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' };
            state.blocks.push(p); 
            if (Math.random() > 0.4) addPickupOnPlatform(p);
        }
    }
    state.enemies = [];
    if (!jumpToBossEnabled) {
      for (let i = 1200; i < doorX - 300; i += 1000) {
        state.enemies.push({ id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: 0, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 0, initialX: i, shootTimer: 0, isShieldActive: true });
        state.enemies.push({ id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0 });
        state.enemies.push({ id: `heavy-flyer-${i}`, pos: { x: i + 600, y: 100 }, vel: { x: 0, y: 0 }, width: 80, height: 65, health: 300, maxHealth: 300, type: 'enemy', enemyType: 'flyer', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0 });
        state.enemies.push({ id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0 });
        state.enemies.push({ id: `rusher-${i}`, pos: { x: i + 800, y: 480 }, vel: { x: 0, y: 0 }, width: 50, height: 70, health: 300, maxHealth: 300, type: 'enemy', enemyType: 'tank', behavior: 'patrol', patrolRange: 0, initialX: i + 800, shootTimer: 0, pauseTimer: 0 });
      }
    }
    state.enemies.push({ id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 666, maxHealth: 666, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0, bossState: 'idle', stateTimer: 60 });
  }, [stageId, jumpToBossEnabled]);

  const respawn = useCallback(() => {
    const state = gameStateRef.current;
    state.player.health = INITIAL_PLAYER_HEALTH; 

    const baseStartX = jumpToBossEnabled ? BOSS_DOOR_X - 800 : 0;
    state.player.pos = { x: baseStartX + 150, y: 100 }; 

    state.player.vel = { x: 0, y: 0 }; 
    state.player.invincibilityTimer = 60; 
    state.player.facing = 1; 
    state.player.isCharging = false;
    state.player.isUppercutting = false;
    state.player.currentWeapon = 'GUN';
    state.player.killSatisfactionTimer = 0;
    state.player.pushbackTimer = 0;
    state.shouldSyncWeapon = true; 
    state.player.weaponAmmo = {
        'GUN': Infinity,
        'BOULDER': MAX_AMMO['BOULDER'],
        'SHOTGUN': MAX_AMMO['SHOTGUN'],
        'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
        'TSUNAMI': MAX_AMMO['TSUNAMI']
    };
    state.deathTimer = 0;
    state.deathString = "";
    state.victoryString = "";
    state.postVictoryTimer = 0;
    state.bossExplosionTimer = 0;
    state.frame = 1; 
    state.arenaLocked = false;
    state.tsunamiActive = false;
    state.doorState = 'closed';
    state.doorOpenAmount = 0;
    state.bossVolcanoes = [];
    state.bossVolcanoTelegraphs = [];
    state.bossPoopTelegraphs = [];
    state.bossSteamExplosions = [];
    state.bossTsunamiSide = 0;
    state.victorWallSide = 0;
    state.ernieVibrationTimer = 0;
    state.playerStunTimer = 0;
    state.screenShakeTimer = 0;

    state.particles = [];
    state.projectiles = [];
    state.pickups = [];
    state.damageNumbers = [];

    createLevel();
  }, [createLevel, jumpToBossEnabled]);

  const checkIsWeakness = (p?: Partial<Projectile>) => {
    if (!p) {
        if (stageId === 'Artie Avalanche' && currentWeapon === 'FLAMETHROWER') return true;
        if (stageId === 'Victor Volcano' && currentWeapon === 'TSUNAMI') return true;
        if (stageId === 'Ernie Earthquake' && currentWeapon === 'SHOTGUN') return true;
        if (stageId === 'Hector Hurricane' && currentWeapon === 'BOULDER') return true;
        return false;
    }
    if (stageId === 'Hector Hurricane' && p.isBoulder) return true;
    if (stageId === 'Victor Volcano' && p.isTsunami) return true;
    if (stageId === 'Artie Avalanche' && (p.owner === 'player' && currentWeapon === 'FLAMETHROWER')) return true;
    if (stageId === 'Artie Avalanche' && currentWeapon === 'FLAMETHROWER') return true;
    if (stageId === 'Ernie Earthquake' && p.isIce) return true;
    return false;
  };

  const getBossDamage = (boss: Enemy, p?: Partial<Projectile>) => {
    if (stageId === 'Victor Volcano' && (p?.isTsunami || (!p && currentWeapon === 'TSUNAMI'))) {
      return 150;
    }
    const isWeak = checkIsWeakness(p);
    return isWeak ? 100 : BULLET_DAMAGE;
  };

  const update = useCallback(() => {
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, pickups, damageNumbers } = state;

    state.frame++;

    if (state.screenShakeTimer > 0) state.screenShakeTimer--;

    if (state.deathTimer > 0) {
        state.deathTimer--;
        if (state.deathTimer === 0) respawn();
        state.particles = state.particles.filter(p => { 
          if (!p.isStuck) {
            p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; 
          }
          return p.life > 0; 
        });
        return;
    }

    if (state.bossExplosionTimer > 0) {
      state.bossExplosionTimer--;
      if (state.frame % 3 === 0) {
        spawnDeathShower(state.bossExplosionPos, (Math.random() - 0.5) * 2, 5.0, true); 
      }
      state.particles = state.particles.filter(p => { 
          if (p.isStuck) return true;
          p.pos.x += p.vel.x; p.pos.y += p.vel.y; 

          if (p.isBossGore) {
            p.vel.y += 0.45; 
            for (const b of blocks) {
                if (b.type === 'pit') continue;
                if (p.pos.x > b.x && p.pos.x < b.x + b.w && p.pos.y > b.y && p.pos.y < b.y + b.h) {
                    p.vel.x = 0; p.vel.y = 0; p.isStuck = true;
                    break;
                }
            }
          }

          if (!p.isStuck) p.life--; 
          return p.life > 0; 
      });

      if (state.bossExplosionTimer <= 0) {
        onBossDeath(); 
        state.victoryString = "V"; 
        state.postVictoryTimer = 0;
      }
      return; 
    }

    if (status === GameStatus.PAUSED) return;

    if (status === GameStatus.LEVEL_INTRO) {
        state.introTimer++; 
        const baseStartX = jumpToBossEnabled ? BOSS_DOOR_X - 800 : 0;
        state.camera.x = baseStartX; 
        state.player.facing = 1; 
        if (state.introTimer === 30 && !jumpToBossEnabled) speakIntroLine(stageId); 
        if (state.introTimer < 80) { state.player.pos.x = baseStartX - 150; } 
        else {
            if (state.introTimer === 80) { playGlassShatterSound(); spawnGlassShatter({ x: baseStartX, y: 450 }); }
            const jumpDuration = 60;
            const t = Math.min(1.0, (state.introTimer - 80) / jumpDuration);
            state.player.pos.x = baseStartX - 100 + (t * 250);
            const peakHeight = 250; const groundY = 486; const startY = 400;
            state.player.pos.y = startY + (groundY - startY) * t - Math.sin(t * Math.PI) * peakHeight;
            if (state.introTimer >= 80 + jumpDuration) { 
              state.player.pos.y = groundY; state.player.pos.x = baseStartX + 150; state.player.vel = { x: 0, y: 0 }; 
              onIntroComplete(); 
            }
        }
        state.particles = state.particles.filter(p => { 
          if (!p.isStuck) {
            p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; 
          }
          return p.life > 0; 
        });
        return;
    }

    if (status === GameStatus.BOSS_TRANSITION) {
        const targetCameraX = BOSS_DOOR_X; 
        const targetPlayerX = targetCameraX + 150; 
        const glideSpeed = 4; 

        if (state.doorState === 'opening') {
            state.doorOpenAmount += 5;
            if (state.doorOpenAmount >= 150) {
                state.doorOpenAmount = 150;
                state.doorState = 'open';
            }
        } else if (state.doorState === 'open') {
            if (state.camera.x < targetCameraX) {
                state.camera.x = Math.min(targetCameraX, state.camera.x + glideSpeed);
            }
            if (player.pos.x < targetPlayerX) {
                player.pos.x = Math.min(targetPlayerX, player.pos.x + glideSpeed);
            }
            if (state.camera.x >= targetCameraX && player.pos.x >= targetPlayerX) {
                state.doorState = 'closing';
            }
        } else if (state.doorState === 'closing') {
            state.doorOpenAmount -= 5;
            if (state.doorOpenAmount <= 0) {
                state.doorOpenAmount = 0;
                state.doorState = 'done';
                player.isCharging = false;
                player.isUppercutting = false;
                onBossEncounter(); 
            }
        }

        player.pos.y += (486 - player.pos.y) * 0.05;
        player.vel = { x: 0, y: 0 };
        player.facing = 1;
        state.projectiles = []; // Clear all projectiles during transition
        return;
    }

    if (status !== GameStatus.PLAYING) {
        if (status === GameStatus.BOSS_INTRO) {
            state.arenaLocked = false;
        }
        return;
    }

    if (player.pos.x >= BOSS_DOOR_X && state.doorState === 'done') {
        state.arenaLocked = true;
    }

    if (state.victoryString) {
      state.particles = state.particles.filter(p => { 
        if (!p.isStuck) {
          p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; 
        }
        return p.life > 0; 
      });
      if (state.victoryString.length < 7) {
        state.postVictoryTimer++;
        if (state.postVictoryTimer >= 30) {
            const fullStr = "VICTORY"; state.victoryString += fullStr[state.victoryString.length]; state.postVictoryTimer = 0;
            if (state.victoryString.length === 7) { setTimeout(() => { onBossDefeated(stageId || ""); }, 2000); }
        }
      }
      return; 
    }

    if (state.tsunamiActive) {
      state.tsunamiX += TSUNAMI_WAVE_SPEED * state.tsunamiDir;
      const dist = Math.abs(state.tsunamiX - state.tsunamiStartX);
      const totalDist = CANVAS_WIDTH * 1.5;
      const progress = dist / totalDist;
      const currentTopY = Math.min(1.0, progress) * 550;
      const waveHeight = 550 - currentTopY;
      const bendMult = 120; 
      const dir = state.tsunamiDir;

      // Particle Visuals
      const density = 35;
      for (let i = 0; i <= density; i++) {
        const yPct = i / density;
        const yPos = currentTopY + (yPct * waveHeight);
        const normalizedY = (yPct - 0.5) * 2; 
        const xOffset = (normalizedY * normalizedY) * bendMult * dir;
        const px = state.tsunamiX + xOffset;
        const py = yPos;

        state.particles.push({
          pos: { x: px + (Math.random() - 0.5) * 40, y: py + (Math.random() - 0.5) * 15 },
          vel: { x: (TSUNAMI_WAVE_SPEED * 0.4 + Math.random() * 8) * dir, y: (Math.random() - 0.5) * 4 },
          life: 12 + Math.random() * 18,
          color: WATER_COLORS[Math.floor(Math.random() * WATER_COLORS.length)],
          size: 8 + Math.random() * 12,
          isWater: true
        });

        if (i < 3 && Math.random() > 0.4) {
           state.particles.push({
            pos: { x: px, y: py },
            vel: { x: (TSUNAMI_WAVE_SPEED * 0.9) * dir, y: (Math.random() - 0.5) * 10 },
            life: 20 + Math.random() * 10,
            color: '#FFFFFF',
            size: 5 + Math.random() * 5,
            isWater: true
          });
        }
      }

      // Tsunami hits Victor's geysers logic
      if (stageId === 'Victor Volcano') {
        state.bossVolcanoes = state.bossVolcanoes.filter(v => {
          const distToWave = Math.abs(v.pos.x - state.tsunamiX);
          if (distToWave < 60) {
            // STEAM EXPLOSION!
            state.bossSteamExplosions.push({ pos: { ...v.pos }, life: 45, radius: 100 });
            spawnSteamExplosionParticles(v.pos, 40);
            state.screenShakeTimer = 12;
            return false; // Volcano is washed away
          }
          return true;
        });
      }

      // Damage Logic
      enemies.forEach(e => {
        if (e.health > 0 && !e.isBlownAway) {
          const eMidX = e.pos.x + e.width / 2;
          const distToWave = Math.abs(eMidX - state.tsunamiX);
          if (distToWave < 120) {
            if (e.type === 'boss') {
              if (state.arenaLocked && (!e.hitCooldown || e.hitCooldown <= 0)) {
                const isWeak = checkIsWeakness();
                const dmg = isWeak ? 100 : 25;
                e.health -= dmg; e.hitCooldown = 45;
                spawnDamageNumber(e.pos, dmg, isWeak);
                if (e.health <= 0) triggerBossDeath(e, state.tsunamiDir, isWeak);
              }
            } else {
              e.health = 0;
              e.isBlownAway = true;
              e.vel = { x: state.tsunamiDir * 20, y: -10 };
              e.rotation = 0;
              spawnDeathShower(e.pos, state.tsunamiDir);
              spawnPickup(e.pos);
              speakVulgarity('tsunami_kill');
              player.killSatisfactionTimer = 60;
            }
          }
        }
      });

      if (progress >= 1.0) {
        state.tsunamiActive = false;
      }
    }

    // Process Steam Explosions Hurtbox
    state.bossSteamExplosions = state.bossSteamExplosions.filter(exp => {
        exp.life--;
        // Hurt player if caught in scalding steam
        const pMidX = player.pos.x + player.width/2;
        const pMidY = player.pos.y + player.height/2;
        const dx = pMidX - exp.pos.x;
        const dy = pMidY - exp.pos.y;
        const distSq = dx*dx + dy*dy;
        if (distSq < exp.radius * exp.radius && player.invincibilityTimer <= 0 && !invincibilityEnabled) {
            player.health -= 12;
            player.invincibilityTimer = 45;
            player.pushbackTimer = 20;
            player.vel.x = dx > 0 ? 18 : -18;
            player.vel.y = -6;
            speakVulgarity('hurt');
        }
        if (state.frame % 3 === 0) spawnSteamExplosionParticles(exp.pos, 6);
        return exp.life > 0;
    });

    const gamepads = navigator.getGamepads();
    let padMoveX = 0, padMoveY = 0, padJump = false, padSpecial = false, padShoot = false;
    if (gamepads[0]) {
      const gp = gamepads[0]; const DEADZONE = 0.2;
      if (Math.abs(gp.axes[0]) > DEADZONE) padMoveX = gp.axes[0];
      if (Math.abs(gp.axes[1]) > DEADZONE) padMoveY = gp.axes[1];
      if (gp.buttons[14]?.pressed) padMoveX = -1;
      if (gp.buttons[15]?.pressed) padMoveX = 1;
      if (gp.buttons[12]?.pressed) padMoveY = -1;
      if (gp.buttons[13]?.pressed) padMoveY = 1;
      padJump = gp.buttons[0]?.pressed; 
      padShoot = gp.buttons[2]?.pressed || gp.buttons[3]?.pressed; 
      padSpecial = gp.buttons[7]?.pressed; 
    }

    const km = keys.current;
    const isStunned = state.playerStunTimer > 0;
    const hasAmmo = (wpn: WeaponType) => wpn === 'GUN' || player.weaponAmmo[wpn] >= 1;
    const shootRequested = !isStunned && player.pushbackTimer <= 0 && (mouse.current.down || padShoot); 
    const isFiringFlamethrower = currentWeapon === 'FLAMETHROWER' && shootRequested && hasAmmo('FLAMETHROWER');

    const moveLeft = !isStunned && player.pushbackTimer <= 0 && (km['a'] || km['arrowleft'] || km['keya'] || padMoveX < -0.3);
    const moveRight = !isStunned && player.pushbackTimer <= 0 && (km['d'] || km['arrowright'] || km['keyd'] || padMoveX > 0.3);
    const moveDown = !isStunned && player.pushbackTimer <= 0 && (km['s'] || km['arrowdown'] || km['keys'] || padMoveY > 0.3);
    const moveUp = !isStunned && player.pushbackTimer <= 0 && (km['w'] || km['arrowup'] || km['keyw'] || padMoveY < -0.3);
    const jumpRequested = !isStunned && player.pushbackTimer <= 0 && (km[' '] || km['space'] || km['z'] || km['keyz'] || km['j'] || km['keyj'] || padJump);
    const chargeRequested = !isStunned && player.pushbackTimer <= 0 && (km['shift'] || km['shiftleft'] || km['shiftright'] || km['c'] || km['keyc'] || padSpecial);

    if (state.playerStunTimer > 0) state.playerStunTimer--;
    if (state.playerVulgarityTimer > 0) { state.playerVulgarityTimer--; if (state.playerVulgarityTimer <= 0) state.playerLastVulgarity = ""; }
    if (state.bossVulgarityTimer > 0) { state.bossVulgarityTimer--; if (state.bossVulgarityTimer <= 0) state.bossLastVulgarity = ""; }
    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;
    if (player.killSatisfactionTimer > 0) player.killSatisfactionTimer--;
    if (player.pushbackTimer > 0) { player.pushbackTimer--; player.vel.x *= 0.9; }

    if (player.specialCharges < MAX_SPECIAL_CHARGES) {
      player.specialChargeTimer++;
      if (player.specialChargeTimer >= SPECIAL_CHARGE_REGEN_FRAMES) { player.specialCharges++; player.specialChargeTimer = 0; }
    }

    if (!jumpRequested) player.jumpInputReleased = true;
    if (!chargeRequested) player.chargeInputReleased = true;

    let totalPullForceX = 0;

    // Lingering Earthquake Stun Window
    if (state.ernieVibrationTimer > 0) {
      state.ernieVibrationTimer--;
      if (player.isGrounded && player.pos.x > BOSS_DOOR_X && player.invincibilityTimer <= 0 && state.playerStunTimer <= 0) {
        state.playerStunTimer = 50;
        player.vel.x = 0;
        speakVulgarity('hurt');
      }
    }

    enemies.forEach(e => {
        if (e.type === 'boss' && e.health > 0 && state.arenaLocked) {
            e.stateTimer = (e.stateTimer || 0) - 1;
            const dirToPlayer = player.pos.x + player.width/2 < e.pos.x + e.width/2 ? -1 : 1;

            const healthPct = (e.health / e.maxHealth) * 100;
            if (stageId && BOSS_THRESHOLDS[stageId]) {
              if (healthPct <= 75 && !e.said75) { e.said75 = true; speakAsBoss(stageId, BOSS_THRESHOLDS[stageId][75]); }
              if (healthPct <= 50 && !e.said50) { e.said50 = true; speakAsBoss(stageId, BOSS_THRESHOLDS[stageId][50]); }
              if (healthPct <= 25 && !e.said25) { e.said25 = true; speakAsBoss(stageId, BOSS_THRESHOLDS[stageId][25]); }
            }

            if (stageId === 'Hector Hurricane') {
                if (e.bossState === 'hurricane') {
                  const forceDir = (e.pos.x + e.width/2 - (player.pos.x + player.width/2)) > 0 ? 1 : -1;
                  totalPullForceX += forceDir * HECTOR_PULL_STRENGTH;

                  // Update all projectiles affected by wind
                  projectiles.forEach(p => {
                    if (p.owner === 'player' && p.isBoulder) {
                      const pullDir = (e.pos.x + e.width/2 - (p.pos.x + p.width/2)) > 0 ? 1 : -1;
                      p.vel.x += pullDir * 1.5; 
                    }
                    if (p.isPoop) {
                       p.vel.x += forceDir * HECTOR_PULL_STRENGTH;
                    }
                  });

                  // Update poop telegraphs
                  state.bossPoopTelegraphs = state.bossPoopTelegraphs.filter(t => {
                      t.life--;
                      if (t.life <= 0) {
                          // Spawn poop log after warning
                          const spawnLeft = t.spawnX === BOSS_DOOR_X;
                          const velX = spawnLeft ? 12 : -12;
                          projectiles.push({ 
                              id: `poop-${Date.now()}`, 
                              pos: { x: t.spawnX, y: t.pos.y }, 
                              vel: { x: velX, y: (Math.random()-0.5)*3 }, 
                              width: 45, height: 20, health: 1, maxHealth: 1, 
                              type: 'projectile', damage: 12, owner: 'enemy', isPoop: true,
                              spawnX: t.spawnX
                          });
                          return false;
                      }
                      return true;
                  });

                  // Trigger a new poop telegraph periodically (Spawn rate: every 110 frames)
                  if (state.frame % 110 === 0) {
                     const spawnLeft = forceDir > 0;
                     const spawnX = spawnLeft ? BOSS_DOOR_X : 8000;

                     const r = Math.random();
                     let spawnY;
                     if (r < 0.33) {
                       spawnY = 510; // Ground level: Hits feet/legs
                     } else if (r < 0.66) {
                       spawnY = 498; // Duckable height
                     } else {
                       spawnY = 440; // Higher level
                     }

                     state.bossPoopTelegraphs.push({
                        pos: { x: spawnX, y: spawnY },
                        life: 45, // 45 frame warning
                        spawnX: spawnX
                     });
                  }

                  const dist = Math.abs((e.pos.x + e.width/2) - (player.pos.x + player.width/2));
                  const stormRadius = 300;
                  if (dist < stormRadius && player.invincibilityTimer <= 0 && !invincibilityEnabled) {
                    player.health -= 4; 
                    player.invincibilityTimer = 25; 
                    player.pushbackTimer = 2;
                    speakVulgarity('hurt');
                  }
                  if (e.stateTimer <= 0) {
                    e.bossState = 'idle';
                    e.stateTimer = 40;
                    state.bossPoopTelegraphs = []; // Clear leftovers
                  }
                } else if (e.bossState === 'jumping') {
                  if (e.isGroundedBoss) {
                    e.bossState = 'hurricane';
                    e.stateTimer = 300; 
                    e.vel.x = 0;
                  }
                } else {
                  if (e.stateTimer <= 0) {
                    e.bossState = 'jumping';
                    e.vel.y = -22 - Math.random() * 4;
                    const targetX = e.pos.x > 7600 ? 7300 : 7900;
                    e.vel.x = (targetX - e.pos.x) * 0.035;
                  }
                }
            } else if (stageId === 'Artie Avalanche') {
                if (e.shootTimer > 0) e.shootTimer--; // global projectile cooldown for Artie

                // TRACK STATIONARY TIME: Use e.sideTimer (unused property for bosses usually)
                if (e.isGroundedBoss && Math.abs(e.vel.x) < 0.5) {
                    e.sideTimer = (e.sideTimer || 0) + 1;
                } else {
                    e.sideTimer = 0;
                }

                if ((e.stateTimer <= 0 || (e.sideTimer || 0) > 175) && e.isGroundedBoss) {
                    const r = Math.random();
                    // Force movement if been stationary too long
                    const mustMove = (e.sideTimer || 0) > 120;

                    if (r < 0.35 || (mustMove && r < 0.6)) { // JUMP
                        e.vel.y = -13 - Math.random() * 3;
                        e.vel.x = (player.pos.x < e.pos.x ? -1 : 1) * (4 + Math.random() * 2);
                        e.stateTimer = 70;
                        e.bossState = 'jumping';
                        e.sideTimer = 0; // Reset stationary timer on jump start
                    } else if (r < 0.70 && e.shootTimer <= 0 && !mustMove) { // SHOOT - Ground
                        const targetDir = player.pos.x < (e.pos.x + e.width/2) ? -1 : 1;
                        const projW = 60;
                        const spawnX = targetDir === 1 ? e.pos.x + e.width + 5 : e.pos.x - projW - 5;
                        const spawnY = e.pos.y + 10;

                        projectiles.push({ 
                          id: `ice-big-${Date.now()}`, 
                          pos: { x: spawnX, y: spawnY }, 
                          vel: { x: targetDir * 11, y: 0 }, 
                          width: projW, height: 60, health: 1, maxHealth: 1, type: 'projectile', 
                          damage: BULLET_DAMAGE, owner: 'enemy', isIce: true 
                        });
                        e.shootTimer = 60; // 1 second projectile cooldown
                        e.stateTimer = 80; 
                        e.bossState = 'attacking';
                    } else { // DASH
                        e.vel.x = dirToPlayer * 7.5;
                        e.stateTimer = 65;
                        e.bossState = 'attacking';
                        e.sideTimer = 0; // Reset stationary timer on dash start
                    }
                }
                if (e.bossState === 'jumping' && !e.isGroundedBoss && e.shootTimer <= 0) {
                   // Air fire logic - strictly limited by shootTimer
                   if (Math.abs(e.vel.y) < 2 && e.stateTimer > 20 && Math.random() < 0.08) { 
                        const targetDir = player.pos.x < (e.pos.x + e.width/2) ? -1 : 1;
                        const projW = 60;
                        const spawnX = targetDir === 1 ? e.pos.x + e.width + 5 : e.pos.x - projW - 5;
                        const spawnY = e.pos.y + 10;
                        projectiles.push({ 
                          id: `ice-big-air-${Date.now()}`, 
                          pos: { x: spawnX, y: spawnY }, 
                          vel: { x: targetDir * 11, y: 0 }, 
                          width: projW, height: 60, health: 1, maxHealth: 1, type: 'projectile', 
                          damage: BULLET_DAMAGE, owner: 'enemy', isIce: true 
                        });
                        e.shootTimer = 60; 
                        e.stateTimer = 50; 
                   }
                }
                if (e.isGroundedBoss) {
                  e.vel.x *= 0.95;
                }
            } else if (stageId === 'Ernie Earthquake') {
                if (e.bossState === 'stunned_drop') {
                    if (e.isGroundedBoss && e.stateTimer <= 0) {
                        e.bossState = 'idle';
                        e.stateTimer = 40;
                        e.rotation = 0;
                    }
                } else if (e.stateTimer <= 0) {
                    e.vel.y = -12; 
                    e.vel.x = (player.pos.x - e.pos.x) * 0.03;
                    e.stateTimer = 180; 
                    projectiles.push({ 
                        id: `b-ernie-jump-${Date.now()}`, 
                        pos: { x: e.pos.x + e.width/2, y: e.pos.y + 20 }, 
                        vel: { x: dirToPlayer * (BOULDER_SPEED + 1), y: 0 }, 
                        width: 48, height: 48, health: 1, maxHealth: 1, 
                        type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isBoulder: true 
                    });
                }
            }

            if (e.bossState !== 'stunned_drop') {
                const gravityMult = (stageId === 'Artie Avalanche' || (stageId === 'Ernie Earthquake' && !e.isGroundedBoss)) ? 0.5 : 1.0;
                e.vel.y += GRAVITY * gravityMult;
                e.pos.x += e.vel.x;
                const prevY = e.pos.y;
                e.pos.y += e.vel.y;

                e.pos.x = Math.max(BOSS_DOOR_X + 10, Math.min(8000 - e.width - 10, e.pos.x));
                if (e.pos.y < 100) { e.pos.y = 100; e.vel.y = 0; }
                if (e.pos.y > 470) {
                    e.pos.y = 470; 
                    if (prevY < 470 && e.vel.y > 0) {
                        if (stageId === 'Ernie Earthquake') {
                            state.screenShakeTimer = 30;
                            state.ernieVibrationTimer = 40; 
                            projectiles.push({ 
                                id: `b-ernie-land-${Date.now()}`, 
                                pos: { x: e.pos.x + e.width/2, y: e.pos.y + 20 }, 
                                vel: { x: dirToPlayer * (BOULDER_SPEED + 1), y: 0 }, 
                                width: 48, height: 48, health: 1, maxHealth: 1, 
                                type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isBoulder: true 
                            });
                        }
                    }
                    e.vel.y = 0; e.vel.x = 0; e.isGroundedBoss = true;
                } else {
                    e.isGroundedBoss = false;
                }
            } else {
                e.vel.y += GRAVITY * 1.5;
                e.pos.y += e.vel.y;
                if (e.pos.y > 470) {
                    e.pos.y = 470;
                    e.vel.y = 0;
                    e.isGroundedBoss = true;
                    if (e.stateTimer > 30) e.stateTimer = 30; 
                }
            }
        }
    });

    state.bossVolcanoes = state.bossVolcanoes.filter(v => {
        v.life--;
        if (state.frame % 12 === 0) {
            const magVelX = v.type === 'wall' ? (v.pos.x < BOSS_DOOR_X + 400 ? 9 : -9) : (Math.random()-0.5)*4;
            const magVelY = v.type === 'ground' ? -9 : (Math.random()-0.5)*7;
            projectiles.push({ id: `magma-${Date.now()}`, pos: { x: v.pos.x, y: v.pos.y }, vel: { x: magVelX, y: magVelY }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 15, owner: 'enemy' });
        }
        return v.life > 0;
    });

    player.isDucking = moveDown && player.isGrounded && !player.isCharging && !player.isUppercutting && !isFiringFlamethrower;

    if (player.jumpPrepTimer > 0) {
      player.jumpPrepTimer--;
      if (player.jumpPrepTimer === 0) { player.vel.y = player.isCharging ? PLAYER_JUMP_FORCE * 1.5 : PLAYER_JUMP_FORCE; player.isGrounded = false; }
    } else {
      if (!player.isCharging && !player.isUppercutting && player.pushbackTimer <= 0 && state.playerStunTimer <= 0) {
        if (!player.isDucking) {
          const speed = isFiringFlamethrower ? PLAYER_SPEED * FLAMETHROWER_SPEED_MULT : PLAYER_SPEED;
          const isIce = stageId === 'Artie Avalanche';
          const accel = isIce ? 0.35 : 2.5; 
          const iceFriction = 0.985;

          if (moveLeft) { 
            player.vel.x = Math.max(-speed, player.vel.x - accel); 
            if(!isFiringFlamethrower) player.facing = -1; 
          }
          else if (moveRight) { 
            player.vel.x = Math.min(speed, player.vel.x + accel); 
            if(!isFiringFlamethrower) player.facing = 1; 
          }
          else {
              if (player.isGrounded) {
                  if (isIce) {
                    player.vel.x *= iceFriction;
                    if (Math.abs(player.vel.x) < 0.1) player.vel.x = 0;
                  } else {
                    player.vel.x = 0; 
                  }
              } else {
                  player.vel.x *= FRICTION;
              }
          }
        } else {
          if (player.isGrounded) {
             if (stageId === 'Artie Avalanche') player.vel.x *= 0.99;
             else player.vel.x = 0;
          }
          else player.vel.x *= FRICTION;
        }
        if (jumpRequested && player.isGrounded && player.jumpInputReleased) { player.jumpPrepTimer = JUMP_PREP_FRAMES; player.jumpInputReleased = false; }
      } else if (player.isCharging) {
        player.chargeDuration--; player.vel.x += player.facing * CHARGE_ACCEL;
        if (Math.abs(player.vel.x) > CHARGE_SPEED) player.vel.x = player.facing * CHARGE_SPEED;
        if (player.chargeDuration <= 0) { player.isCharging = false; player.vel.x = player.facing * PLAYER_SPEED; }
      } else if (player.isUppercutting) {
        player.chargeDuration--;
        if (player.chargeDuration <= 0) player.isUppercutting = false;
      }

      if (totalPullForceX !== 0) {
        player.vel.x += totalPullForceX;
      }

      if (chargeRequested && player.chargeInputReleased && !player.isCharging && !player.isUppercutting && !player.isDucking && player.specialCharges > 0 && !isFiringFlamethrower && state.playerStunTimer <= 0) {
        player.chargeInputReleased = false; 
        player.specialCharges--; 
        player.chargeDuration = CHARGE_DURATION;
        if (moveUp) { 
          player.isUppercutting = true; 
          player.vel.y = UPPERCUT_FORCE; 
          player.isGrounded = false; 
          player.vel.x = 0; 
        } else { 
          player.isCharging = true; 
          player.vel.x = player.facing * 5; 
        }
      }

      if (shootRequested && player.shootCooldown <= 0 && hasAmmo(currentWeapon)) {
        if (currentWeapon === 'GUN') {
          projectiles.push({ id: `p-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: player.facing * 18, y: 0 }, width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'player' });
          player.shootCooldown = 12; playGunSound('gun');
        } else if (currentWeapon === 'BOULDER') {
          if (!projectiles.some(p => p.owner === 'player' && p.isBoulder)) {
            const vy = moveUp ? -18 : 0;
            const vx = moveUp ? player.facing * (BOULDER_SPEED * 0.9) : player.facing * BOULDER_SPEED;
            projectiles.push({ id: `b-${Date.now()}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -40), y: player.pos.y + 20 }, vel: { x: vx, y: vy }, width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BOULDER_DAMAGE, owner: 'player', isBoulder: true });
            player.shootCooldown = 40; if (!infiniteAmmoEnabled) player.weaponAmmo['BOULDER']--;
          }
        } else if (currentWeapon === 'SHOTGUN') {
          for (let i = 0; i < 7; i++) {
            const angle = (i - 3) * 0.15; const speed = 11 + Math.random() * 6;
            projectiles.push({ id: `pellet-${Date.now()}-${i}`, pos: { x: player.pos.x + (player.facing === 1 ? player.width : -10), y: player.isDucking ? player.pos.y + 45 : player.pos.y + 25 }, vel: { x: Math.cos(angle) * player.facing * speed, y: Math.sin(angle) * speed }, width: 10, height: 10, health: 1, maxHealth: 1, type: 'projectile', damage: SHOTGUN_DAMAGE, owner: 'player', isIce: true });
          }
          player.shootCooldown = SHOTGUN_COOLDOWN; playGunSound('ice'); if (!infiniteAmmoEnabled) player.weaponAmmo['SHOTGUN']--;
        } else if (currentWeapon === 'FLAMETHROWER') {
            if (state.frame % 2 === 0) {
                if (!infiniteAmmoEnabled) player.weaponAmmo['FLAMETHROWER']--; 
                playGunSound('flame');
                for (let i = 0; i < 6; i++) {
                    const angle = (Math.random() - 0.5) * 0.6; const speed = 8 + Math.random() * 8;
                    const flameColor = FIRE_COLORS[Math.floor(Math.random() * FIRE_COLORS.length)];
                    state.particles.push({ pos: { x: player.pos.x + (player.facing === 1 ? player.width - 5 : 5), y: player.pos.y + 30 }, vel: { x: Math.cos(angle) * player.facing * speed + player.vel.x, y: Math.sin(angle) * speed }, life: 15 + Math.random() * 20, color: flameColor, size: 8 + Math.random() * 12 });
                }
                const fRect = { x: player.facing === 1 ? player.pos.x + player.width : player.pos.x - FLAMETHROWER_RANGE, y: player.pos.y + 10, w: FLAMETHROWER_RANGE, h: 50 };
                state.projectiles.forEach(p => {
                    if (p.owner === 'enemy' && p.pos.x < fRect.x + fRect.w && p.pos.x + p.width > fRect.x && p.pos.y < fRect.y + fRect.h && p.pos.y + p.height > fRect.y) {
                        const isGiantIce = p.isIce && p.width > 30;
                        const isInvincibleBossProjectile = p.id.startsWith('debris-') || p.id.startsWith('magma-') || (p.isBoulder && p.owner === 'enemy') || (p.isIce && p.width <= 20); 

                        if (isGiantIce || !isInvincibleBossProjectile) {
                            p.health = 0;
                            const pColor = p.isIce ? COLORS.PROJECTILE_ICE : (p.id.startsWith('magma') ? '#FF4500' : COLORS.PROJECTILE_ENEMY);
                            const pCount = Math.min(10, Math.ceil(p.width / 5));
                            const pParticleSize = Math.max(2, p.width / 8);
                            spawnExplosion({ x: p.pos.x + p.width/2, y: p.pos.y + p.height/2 }, pColor, pCount, 0, 10);
                        }
                    }
                });
                state.enemies.forEach(enemy => {
                    if (enemy.health > 0 && !enemy.isBlownAway) {
                        if (enemy.pos.x < fRect.x + fRect.w && enemy.pos.x + enemy.width > fRect.x && enemy.pos.y < fRect.y + fRect.h && enemy.pos.y + enemy.height > fRect.y) {
                            if (enemy.type === 'boss') {
                                if (state.arenaLocked) {
                                    if (!enemy.hitCooldown || enemy.hitCooldown <= 0) {
                                        const dmg = getBossDamage(enemy);
                                        const isWeak = checkIsWeakness();
                                        enemy.health -= dmg; enemy.hitCooldown = 60;
                                        spawnDamageNumber(enemy.pos, dmg, isWeak);
                                        if (stageId === 'Artie Avalanche' && isWeak && enemy.health > 0) {
                                            const targetX = enemy.pos.x < 7560 ? 7850 : 7250;
                                            enemy.vel.y = -22; 
                                            enemy.vel.x = (targetX - enemy.pos.x) / 50; 
                                            enemy.bossState = 'jumping';
                                            enemy.stateTimer = 60;
                                        }
                                        if (enemy.health <= 0) triggerBossDeath(enemy, player.facing, isWeak);
                                    } else {
                                        // VISUAL ONLY BURNING EFFECT DURING BOSS IFRAMES
                                        const particleIntensity = stageId === 'Artie Avalanche' ? 4 : 2;
                                        for (let i = 0; i < particleIntensity; i++) {
                                            const fireColor = FIRE_COLORS[Math.floor(Math.random() * FIRE_COLORS.length)];
                                            state.particles.push({
                                                pos: { x: enemy.pos.x + Math.random() * enemy.width, y: enemy.pos.y + Math.random() * enemy.height },
                                                vel: { x: (Math.random() - 0.5) * 6, y: -Math.random() * 8 - 2 },
                                                life: 15 + Math.random() * 20,
                                                color: fireColor,
                                                size: 6 + Math.random() * 10
                                            });
                                        }
                                        // Add steam/melting visuals specifically for Artie
                                        if (stageId === 'Artie Avalanche' && state.frame % 3 === 0) {
                                             state.particles.push({
                                                pos: { x: enemy.pos.x + Math.random() * enemy.width, y: enemy.pos.y + Math.random() * enemy.height },
                                                vel: { x: (Math.random() - 0.5) * 4, y: -Math.random() * 6 },
                                                life: 20 + Math.random() * 20,
                                                color: '#FFFFFF',
                                                size: 4 + Math.random() * 8
                                            });
                                        }
                                    }
                                }
                            } else {
                                enemy.health -= FLAMETHROWER_DAMAGE;
                                spawnDamageNumber(enemy.pos, FLAMETHROWER_DAMAGE);
                                if (enemy.health <= 0) { 
                                  spawnDeathShower(enemy.pos, player.facing); 
                                  spawnPickup(enemy.pos); 
                                  speakVulgarity('flamethrower_kill'); 
                                  player.killSatisfactionTimer = 60; 
                                }
                            }
                        }
                    }
                });
            }
        } else if (currentWeapon === 'TSUNAMI') {
            if (!state.tsunamiActive) {
                state.tsunamiActive = true; 
                state.tsunamiDir = player.facing; 
                state.tsunamiStartX = player.facing === 1 ? state.camera.x : state.camera.x + CANVAS_WIDTH; 
                state.tsunamiX = state.tsunamiStartX; 
                player.shootCooldown = TSUNAMI_COOLDOWN; 
                playGunSound('tsunami'); 
                if (!infiniteAmmoEnabled) player.weaponAmmo['TSUNAMI']--;
            }
        }
      }
    }

    if (player.shootCooldown > 0) player.shootCooldown--;
    player.vel.y += GRAVITY;
    if (!jumpRequested && player.vel.y < 0 && !player.isGrounded && !player.isCharging && !player.isUppercutting) player.vel.y *= 0.5;

    if (state.playerStunTimer > 0) {
      player.pos.y += (state.frame % 2 === 0 ? -2 : 2);
    }

    player.pos.x += player.vel.x; player.pos.y += player.vel.y;
    if (player.pos.x < 50) player.pos.x = 50;
    if (state.arenaLocked && player.pos.y < 100) { player.pos.y = 100; player.vel.y = 0; }

    player.isGrounded = false;
    blocks.forEach(block => {
      if (block.type === 'door') {
        if (state.doorState === 'opening' || state.doorState === 'open' || state.doorState === 'closing') return;
      }
      if (block.type === 'pit') return; 
      if (player.pos.x < block.x + block.w && player.pos.x + player.width > block.x && player.pos.y < block.y + block.h && player.pos.y + player.height > block.y) {
        if (block.type === 'door' && state.doorState === 'closed') { 
          state.doorState = 'opening'; 
          player.vel.x = 0;
          player.vel.y = 0;
          state.projectiles = []; 
          state.enemies.forEach(e => {
            if (e.type !== 'boss' && e.health > 0) {
                e.health = 0;
                spawnDeathShower(e.pos, 0, 1);
                spawnPickup(e.pos);
            }
          });
          onBossTransition(); 
          return; 
        }
        const overlapX = Math.min(player.pos.x + player.width - block.x, block.x + block.w - player.pos.x);
        const overlapY = Math.min(player.pos.y + player.height - block.y, block.y + block.h - player.pos.y);
        if (overlapX < overlapY) { player.pos.x = (player.pos.x + player.width / 2 < block.x + block.w / 2) ? block.x - player.width : block.x + block.w; player.vel.x = 0; if (player.isCharging) player.isCharging = false; }
        else { if (player.pos.y + player.height / 2 < block.y + block.h / 2) { player.pos.y = block.y - player.height; player.isGrounded = true; player.hasUsedAirMove = false; player.vel.y = 0; } else { player.pos.y = block.y + block.h; player.vel.y = 0; } }
      }
    });

    state.enemies = enemies.filter(enemy => {
      if (enemy.isBlownAway) { enemy.pos.x += enemy.vel.x; enemy.pos.y += enemy.vel.y; enemy.vel.y += GRAVITY * 0.5; enemy.rotation = (enemy.rotation || 0) + 0.3; return enemy.pos.y < 1000; }
      if (enemy.health <= 0) return false; 
      if (enemy.hitCooldown && enemy.hitCooldown > 0) enemy.hitCooldown--;
      if (enemy.frozenTimer && enemy.frozenTimer > 0) { enemy.frozenTimer--; return true; } 
      const onScreen = enemy.pos.x + enemy.width > state.camera.x && enemy.pos.x < state.camera.x + CANVAS_WIDTH;

      const isStunned = (enemy.pauseTimer || 0) > 0;

      if (enemy.enemyType === 'flyer' && !isStunned) {
          enemy.pos.y += Math.sin((state.frame + (enemy.initialX || 0)) / 25) * 1.2;
      }

      if (enemy.type !== 'boss') {
        if (isStunned) {
           enemy.pauseTimer!--;
           if (enemy.id.startsWith('rusher')) {
               enemy.vel.x *= 0.92;
               enemy.pos.x += enemy.vel.x;
           }
        } else {
            if (enemy.id.startsWith('rusher')) {
                const yDiff = Math.abs((player.pos.y + player.height/2) - (enemy.pos.y + enemy.height/2));
                const onSameLevel = yDiff < 80;
                if (onScreen && player.invincibilityTimer <= 0 && onSameLevel) { 
                    enemy.vel.x = (player.pos.x < enemy.pos.x ? -1 : 1) * 6; 
                } else { 
                    enemy.vel.x = 0; 
                }
            } else if (enemy.behavior === 'patrol' || enemy.behavior === 'fly') {
                if (enemy.pos.x > (enemy.initialX + enemy.patrolRange) || enemy.pos.x < enemy.initialX) {
                    enemy.vel.x *= -1;
                }
            } else if (enemy.behavior === 'shoot' && onScreen) {
              enemy.shootTimer++;
              if (enemy.enemyType === 'shield') {
                  enemy.isShieldActive = enemy.shootTimer < 80;
                  if (enemy.shootTimer > 120) { projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x, y: enemy.pos.y + 10 }, vel: { x: -6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' }); enemy.shootTimer = 0; }
              } else if (enemy.shootTimer > 60) {
                  const projY = enemy.enemyType === 'flyer' ? enemy.pos.y + enemy.height - 10 : enemy.pos.y + 10;
                  projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x + enemy.width/2, y: projY }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' }); enemy.shootTimer = 0;
              }
            }
            enemy.pos.x += enemy.vel.x;
        }
      }

      let hbW = player.width, hbH = player.height, hbX = player.pos.x, hbY = player.pos.y;
      if (player.isCharging) { hbW = player.width + 10; hbH = player.height - 10; }
      else if (player.isUppercutting) { hbW = player.width - 15; hbH = player.height + 40; hbY = player.pos.y - 30; hbX = player.pos.x + 7.5; }
      const chargeHit = (player.isCharging || player.isUppercutting) && hbX < enemy.pos.x + enemy.width && hbX + hbW > enemy.pos.x && hbY < enemy.pos.y + enemy.height && hbY + hbH > enemy.pos.y;
      if (chargeHit && onScreen && (!enemy.hitCooldown || enemy.hitCooldown <= 0)) {
        if (enemy.type === 'boss' && !state.arenaLocked) {
           const pushDir = player.pos.x + player.width/2 < enemy.pos.x + enemy.width/2 ? -1 : 1;
           player.vel = { x: pushDir * 18, y: -4 }; player.pushbackTimer = 20; 
           return true;
        }

        if (enemy.id === 'boss' && stageId === 'Hector Hurricane' && enemy.bossState === 'hurricane') {
          enemy.stateTimer = 0; 
        }

        const damage = player.isUppercutting 
