interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (h: number, sc: number, st: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => void;
  onBossEncounter: () => void;
  onBossTransition: () => void;
  onBossDefeated: (stageId: string) => void;
  onBossDeath: () => void;
  onGameOver: (victory: boolean) => void;
  onIntroComplete: () => void;
  onTogglePause: () => void;
  currentWeapon: WeaponType;
  initialAmmo: Record<WeaponType, number>;
  invincibilityEnabled: boolean;
  infiniteAmmoEnabled: boolean;
  jumpToBossEnabled: boolean;
  bossTauntText: string;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  status, stageId, onPlayerUpdate, onBossEncounter, onBossTransition, onBossDefeated, onBossDeath, onGameOver, onIntroComplete, onTogglePause, 
  currentWeapon, initialAmmo, invincibilityEnabled, infiniteAmmoEnabled, jumpToBossEnabled, bossTauntText 
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef<{
    player: Player;
    enemies: Enemy[];
    projectiles: Projectile[];
    particles: Particle[];
    damageNumbers: DamageNumber[];
    cameraX: number;
    frame: number;
    keys: Record<string, boolean>;
    mouse: { x: number, y: number, down: boolean };
    isBossFight: boolean;
    boss?: Enemy;
  } | null>(null);

  const initGame = useCallback(() => {
    const player: Player = {
      id: 'player', pos: { x: 100, y: 400 }, vel: { x: 0, y: 0 }, width: 40, height: 50, health: INITIAL_PLAYER_HEALTH, maxHealth: INITIAL_PLAYER_HEALTH, type: 'player',
      isCharging: false, isUppercutting: false, isDucking: false, specialCharges: 2, specialChargeTimer: 0, chargeDuration: 0,
      isJumping: false, isGrounded: false, facing: 1, shootCooldown: 0, jumpPrepTimer: 0, landTimer: 0, invincibilityTimer: 0, pushbackTimer: 0,
      killSatisfactionTimer: 0, bossKillSatisfactionTimer: 0, hasUsedAirMove: false, jumpInputReleased: true, chargeInputReleased: true,
      currentWeapon: 'GUN', availableWeapons: ['GUN'], weaponAmmo: { ...initialAmmo }
    };

    const enemies: Enemy[] = [];
    for (let i = 0; i < 20; i++) {
      enemies.push({
        id: `enemy-${i}`, pos: { x: 800 + i * 450, y: 450 }, vel: { x: 0, y: 0 }, width: 30, height: 30, health: 50, maxHealth: 50, type: 'enemy',
        enemyType: i % 3 === 0 ? 'tank' : (i % 3 === 1 ? 'flyer' : 'drone'),
        behavior: i % 3 === 1 ? 'fly' : 'patrol', patrolRange: 150, initialX: 800 + i * 450, shootTimer: Math.random() * 100
      });
    }

    gameStateRef.current = {
      player, enemies, projectiles: [], particles: [], damageNumbers: [],
      cameraX: 0, frame: 0, keys: {}, mouse: { x: 0, y: 0, down: false }, isBossFight: false
    };
  }, [initialAmmo]);

  useEffect(() => {
    if (status === GameStatus.LEVEL_INTRO || status === GameStatus.START) {
      initGame();
    }
  }, [status, initGame]);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent, down: boolean) => {
      if (gameStateRef.current) {
        const key = e.key.toLowerCase();
        gameStateRef.current.keys[key] = down;
        if (!down) {
          if (key === ' ' || key === 'w' || key === 'arrowup') gameStateRef.current.player.jumpInputReleased = true;
          if (key === 'shift') gameStateRef.current.player.chargeInputReleased = true;
        }
      }
    };
    const handleMouse = (e: MouseEvent, down: boolean) => {
      if (gameStateRef.current) gameStateRef.current.mouse.down = down;
    };
    const onMove = (e: MouseEvent) => {
      if (canvasRef.current && gameStateRef.current) {
        const rect = canvasRef.current.getBoundingClientRect();
        gameStateRef.current.mouse.x = e.clientX - rect.left;
        gameStateRef.current.mouse.y = e.clientY - rect.top;
      }
    };
    window.addEventListener('keydown', (e) => handleKey(e, true));
    window.addEventListener('keyup', (e) => handleKey(e, false));
    window.addEventListener('mousedown', (e) => handleMouse(e, true));
    window.addEventListener('mouseup', (e) => handleMouse(e, false));
    window.addEventListener('mousemove', onMove);
    return () => {
      window.removeEventListener('keydown', (e) => handleKey(e, true));
      window.removeEventListener('keyup', (e) => handleKey(e, false));
      window.removeEventListener('mousedown', (e) => handleMouse(e, true));
      window.removeEventListener('mouseup', (e) => handleMouse(e, false));
      window.removeEventListener('mousemove', onMove);
    };
  }, []);

  useEffect(() => {
    if (status !== GameStatus.PLAYING && status !== GameStatus.BOSS_INTRO && status !== GameStatus.BOSS_TRANSITION) return;
    let raf: number;

    const spawnVulgarity = (pos: Vector2, pool: string[]) => {
      gameStateRef.current?.damageNumbers.push({
        id: `v-${Math.random()}`, value: 0, text: pool[Math.floor(Math.random() * pool.length)],
        pos: { x: pos.x, y: pos.y - 30 }, vel: { x: 0, y: -2 }, life: 60, maxLife: 60, isCritical: true
      });
    };

    const update = () => {
      const state = gameStateRef.current;
      if (!state || status !== GameStatus.PLAYING) return;
      state.frame++;
      const { player, enemies, projectiles, particles, damageNumbers } = state;

      // Physics
      let dx = 0;
      if (state.keys['a'] || state.keys['arrowleft']) dx -= 1;
      if (state.keys['d'] || state.keys['arrowright']) dx += 1;

      if (player.pushbackTimer > 0) {
        player.pushbackTimer--;
      } else if (player.isCharging) {
        player.vel.x = player.facing * CHARGE_SPEED;
        if (--player.chargeDuration <= 0) player.isCharging = false;
      } else {
        player.vel.x += dx * PLAYER_SPEED * 0.15;
        player.vel.x *= FRICTION;
        if (dx !== 0) player.facing = dx > 0 ? 1 : -1;
      }
      player.vel.y += GRAVITY;

      if ((state.keys[' '] || state.keys['w'] || state.keys['arrowup']) && player.isGrounded && player.jumpInputReleased) {
        player.vel.y = PLAYER_JUMP_FORCE;
        player.isGrounded = false;
        player.jumpInputReleased = false;
      }

      if (state.keys['shift'] && player.chargeInputReleased && player.specialCharges > 0 && !player.isCharging && !player.isUppercutting) {
        if (state.keys['w'] || state.keys['arrowup']) {
          player.isUppercutting = true; player.vel.y = UPPERCUT_FORCE; player.specialCharges--;
        } else {
          player.isCharging = true; player.chargeDuration = CHARGE_DURATION; player.specialCharges--;
        }
        player.chargeInputReleased = false;
      }

      player.pos.x += player.vel.x;
      player.pos.y += player.vel.y;

      const groundY = CANVAS_HEIGHT - 100;
      if (player.pos.y + player.height > groundY) {
        player.pos.y = groundY - player.height;
        player.vel.y = 0; player.isGrounded = true; player.isUppercutting = false;
      }
      player.pos.x = Math.max(state.cameraX, player.pos.x);

      // Camera & Boss trigger
      if (!state.isBossFight) {
        state.cameraX = Math.max(state.cameraX, player.pos.x - 300);
        if (state.cameraX > 6000 || jumpToBossEnabled) {
          state.isBossFight = true; onBossTransition();
          state.boss = {
            id: 'boss', pos: { x: state.cameraX + 700, y: groundY - 120 }, vel: { x: 0, y: 0 }, width: 100, height: 120, health: 1200, maxHealth: 1200, type: 'boss',
            enemyType: 'tank', behavior: 'shoot', patrolRange: 200, initialX: state.cameraX + 700, shootTimer: 50
          };
          onBossEncounter();
        }
      }

      // Shooting
      if (player.shootCooldown > 0) player.shootCooldown--;
      if (state.mouse.down && player.shootCooldown <= 0) {
        if (currentWeapon === 'GUN') {
          projectiles.push({ id: `p-${state.frame}`, pos: { x: player.pos.x + (player.facing > 0 ? 40 : -10), y: player.pos.y + 20 }, vel: { x: player.facing * 12, y: 0 }, width: 15, height: 8, damage: BULLET_DAMAGE, owner: 'player', health: 1, maxHealth: 1, type: 'projectile' });
          player.shootCooldown = 8;
        } else if (currentWeapon === 'BOULDER' && (player.weaponAmmo.BOULDER > 0 || infiniteAmmoEnabled)) {
          projectiles.push({ id: `b-${state.frame}`, pos: { x: player.pos.x, y: player.pos.y - 20 }, vel: { x: player.facing * 8, y: -6 }, width: 30, height: 30, damage: BOULDER_DAMAGE, owner: 'player', isBoulder: true, health: 1, maxHealth: 1, type: 'projectile' });
          if (!infiniteAmmoEnabled) player.weaponAmmo.BOULDER--; player.shootCooldown = 25;
        } else if (currentWeapon === 'SHOTGUN' && (player.weaponAmmo.SHOTGUN > 0 || infiniteAmmoEnabled)) {
          for(let i=0; i<5; i++) projectiles.push({ id: `s-${state.frame}-${i}`, pos: { x: player.pos.x+20, y: player.pos.y+20 }, vel: { x: player.facing*(8+Math.random()*4), y: -2+Math.random()*4 }, width: 8, height: 8, damage: SHOTGUN_DAMAGE, owner: 'player', isIce: true, life: 30, health: 1, maxHealth: 1, type: 'projectile' });
          if (!infiniteAmmoEnabled) player.weaponAmmo.SHOTGUN--; player.shootCooldown = SHOTGUN_COOLDOWN;
        }
      }

      // Update HUD
      onPlayerUpdate(player.health, player.specialCharges, player.specialChargeTimer, player.weaponAmmo, player.currentWeapon);

      // Collisions & Cleanup
      for (let i = projectiles.length-1; i>=0; i--) {
        const p = projectiles[i]; p.pos.x += p.vel.x; p.pos.y += p.vel.y;
        if (p.isBoulder) { p.vel.y += 0.3; if(p.pos.y + p.height > groundY) { p.pos.y = groundY-p.height; p.vel.y *= -0.5; } }
        if (p.owner === 'player') {
          enemies.forEach(e => { if(rectOverlap(p, e)) { e.health -= p.damage; p.health=0; if(e.health<=0) spawnVulgarity(e.pos, GUN_KILL_VULGARITIES); } });
          if (state.boss && rectOverlap(p, state.boss)) { state.boss.health -= p.damage; p.health=0; }
        } else if (rectOverlap(p, player) && !invincibilityEnabled && player.invincibilityTimer <= 0) {
          player.health -= p.damage; player.invincibilityTimer = 60; spawnVulgarity(player.pos, HURT_VULGARITIES); p.health=0;
        }
        if (p.health <= 0 || p.pos.x < state.cameraX - 100 || p.pos.x > state.cameraX + CANVAS_WIDTH + 100) projectiles.splice(i, 1);
      }
      for (let i = enemies.length-1; i>=0; i--) { if(enemies[i].health <= 0) enemies.splice(i, 1); }
      if (state.boss && state.boss.health <= 0) { onBossDeath(); onBossDefeated(stageId || 'default'); state.boss = undefined; }
      if (player.health <= 0) onGameOver(false);
    };

    const rectOverlap = (a: any, b: any) => a.pos.x < b.pos.x + b.width && a.pos.x + a.width > b.pos.x && a.pos.y < b.pos.y + b.height && a.pos.y + a.height > b.pos.y;

    const draw = () => {
      const canvas = canvasRef.current;
      const ctx = canvas?.getContext('2d');
      const state = gameStateRef.current;
      if (!ctx || !state) return;
      const theme = STAGE_COLORS[stageId || 'Artie Avalanche'];
      ctx.fillStyle = theme.bg; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
      ctx.fillStyle = theme.ground; ctx.fillRect(0, CANVAS_HEIGHT-100, CANVAS_WIDTH, 100);
      ctx.save(); ctx.translate(-state.cameraX, 0);
      // Draw Player
      if (state.player.invincibilityTimer % 10 < 5) {
        ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(state.player.pos.x, state.player.pos.x, state.player.width, state.player.height);
        if (state.player.invincibilityTimer > 0) state.player.invincibilityTimer--;
      }
      // Draw Enemies & Boss
      state.enemies.forEach(e => { ctx.fillStyle = COLORS.ENEMY_TANK; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); });
      if (state.boss) { ctx.fillStyle = COLORS.ENEMY_TANK; ctx.fillRect(state.boss.pos.x, state.boss.pos.y, state.boss.width, state.boss.height); }
      // Projectiles
      state.projectiles.forEach(p => { ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
      // Text
      state.damageNumbers.forEach(d => { ctx.fillStyle = 'yellow'; ctx.font = 'bold 14px sans-serif'; ctx.fillText(d.text || '', d.pos.x, d.pos.y); if(--d.life <= 0) state.damageNumbers.splice(state.damageNumbers.indexOf(d), 1); });
      ctx.restore();
    };

    const loop = () => { update(); draw(); raf = requestAnimationFrame(loop); };
    loop(); return () => cancelAnimationFrame(raf);
  }, [status, stageId, currentWeapon, invincibilityEnabled, infiniteAmmoEnabled, jumpToBossEnabled]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black" />;
};

export default GameCanvas;

