    if (p.isUppercutting) { 
      drawH += 30; drawW -= 10; drawY -= 30; drawX += 5; 
      ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 5, drawY - 5, drawW + 10, drawH + 10); ctx.globalAlpha = 1.0; 
    } else if (p.isCharging) { 
      drawW += 20; 
      ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0; 
    }

    const isFlashing = (p.invincibilityTimer > 0 || invincibilityEnabled) && Math.floor(gameStateRef.current.frame / 5) % 2 === 0;

    // Body
    if (!isFlashing) { 
      ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6); 
      ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4); 
    }

    // Facial Positions
    const eyeY = drawY + (p.isDucking ? 5 : 10), eyeSpacing = 12, eyeSize = 6, centerX = drawX + drawW / 2;
    const leftEyeX = centerX - (p.facing === 1 ? eyeSpacing / 2 : eyeSpacing / 2 + 5);
    const rightEyeX = centerX + (p.facing === 1 ? eyeSpacing / 2 + 5 : eyeSpacing / 2);
    const mouthYOffset = p.isDucking ? 7 : 22;

    // --- DRAW BROWS ---
    ctx.save();
    ctx.strokeStyle = 'black';
    if (state.victoryString !== "" || p.bossKillSatisfactionTimer > 0) {
      ctx.lineWidth = 5; // EXTREME FURROW FOR BOSS KILL
      ctx.beginPath(); ctx.moveTo(leftEyeX - 14, eyeY - 16); ctx.lineTo(leftEyeX + 6, eyeY - 6); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(rightEyeX + 14, eyeY - 16); ctx.lineTo(rightEyeX - 6, eyeY - 6); ctx.stroke();
    } else if (p.invincibilityTimer > 15 || p.killSatisfactionTimer > 0) {
      // Hurt or SATISFIED (regular enemy kill) => FURROWED BROWS
      ctx.lineWidth = 4;
      ctx.beginPath(); ctx.moveTo(leftEyeX - 11, eyeY - 13); ctx.lineTo(leftEyeX + 4, eyeY - 5); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(rightEyeX + 11, eyeY - 13); ctx.lineTo(rightEyeX - 4, eyeY - 5); ctx.stroke();
    } else if (p.pushbackTimer > 0) {
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(leftEyeX - 8, eyeY - 14); ctx.quadraticCurveTo(leftEyeX, eyeY - 20, leftEyeX + 8, eyeY - 14); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(rightEyeX - 8, eyeY - 14); ctx.quadraticCurveTo(rightEyeX, eyeY - 20, rightEyeX + 8, eyeY - 14); ctx.stroke();
    } else {
      ctx.lineWidth = 3;
      ctx.beginPath(); ctx.moveTo(leftEyeX - 10, eyeY - 12); ctx.lineTo(leftEyeX + 2, eyeY - 6); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(rightEyeX + 10, eyeY - 12); ctx.lineTo(rightEyeX - 2, eyeY - 6); ctx.stroke();
    }
    ctx.restore();

    // --- DRAW EYES ---
    ctx.save();
    if (state.victoryString !== "" || p.bossKillSatisfactionTimer > 0) {
      ctx.fillStyle = '#ff0000'; // EVIL GLOWING RED EYES FOR BOSS KILL
      ctx.shadowBlur = 10; ctx.shadowColor = 'red';
      ctx.beginPath(); ctx.arc(leftEyeX, eyeY, eyeSize + 3, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(rightEyeX, eyeY, eyeSize + 3, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = 'white'; ctx.shadowBlur = 0;
      ctx.beginPath(); ctx.arc(leftEyeX, eyeY, 3, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(rightEyeX, eyeY, 3, 0, Math.PI * 2); ctx.fill();
    } else if (p.invincibilityTimer > 15) {
      // SMALLER BLOODSHOT EYES FOR HURT STATE
      ctx.fillStyle = '#ffaaaa'; 
      ctx.beginPath(); ctx.arc(leftEyeX, eyeY, eyeSize + 1, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(rightEyeX, eyeY, eyeSize + 1, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = 'red';
      ctx.beginPath(); ctx.arc(leftEyeX, eyeY, 3, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(rightEyeX, eyeY, 3, 0, Math.PI * 2); ctx.fill();
    } else if (p.pushbackTimer > 0) {
      ctx.fillStyle = 'white';
      ctx.beginPath(); ctx.arc(leftEyeX, eyeY, eyeSize + 6, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(rightEyeX, eyeY, eyeSize + 6, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = 'black';
      ctx.beginPath(); ctx.arc(leftEyeX, eyeY, 2, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(rightEyeX, eyeY, 2, 0, Math.PI * 2); ctx.fill();
    } else {
      // DEFAULT: CLOSED/SQUINTED EYES
      ctx.strokeStyle = 'black';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(leftEyeX - 5, eyeY); ctx.lineTo(leftEyeX + 5, eyeY);
      ctx.stroke();
      ctx.beginPath();
      // Fixed: changed 'civ' to 'ctx' below
      ctx.moveTo(rightEyeX - 5, eyeY); ctx.lineTo(rightEyeX + 5, eyeY);
      ctx.stroke();
    }
    // Stunned halo
    if (gameStateRef.current.playerStunTimer > 0) { 
      ctx.fillStyle = 'yellow'; ctx.beginPath(); ctx.arc(centerX, eyeY - 20, 10, 0, Math.PI * 2); ctx.fill(); 
    }
    ctx.restore();

    // --- DRAW MOUTH ---
    ctx.save();
    if (p.bossKillSatisfactionTimer > 0) {
        // --- DEVILISH BLOODY GRIN FOR BOSS KILL ---
        const grinW = 40, grinH = 22;
        const offsetM = eyeY + mouthYOffset;

        // Background black area
        ctx.fillStyle = '#100'; 
        ctx.beginPath();
        ctx.moveTo(centerX - grinW/2, offsetM - 8);
        ctx.quadraticCurveTo(centerX, offsetM + grinH/2, centerX + grinW/2, offsetM - 8);
        ctx.quadraticCurveTo(centerX, offsetM + grinH, centerX - grinW/2, offsetM - 8);
        ctx.fill();

        // Sharp jagged teeth
        ctx.fillStyle = 'white';
        for(let i=0; i<7; i++) {
          const tx = centerX - grinW/2.5 + (i * (grinW/8));
          ctx.beginPath();
          ctx.moveTo(tx, offsetM - 4);
          ctx.lineTo(tx + 2, offsetM + 6);
          ctx.lineTo(tx + 4, offsetM - 4);
          ctx.fill();
        }

        // Blood stains / Bloody highlights
        ctx.fillStyle = '#900';
        ctx.fillRect(centerX - grinW/2, offsetM - 2, 4, 8); // Corner blood
        ctx.fillRect(centerX + grinW/2 - 4, offsetM - 4, 4, 10); // Corner blood
        ctx.globalAlpha = 0.5;
        ctx.fillStyle = '#f00';
        ctx.beginPath(); ctx.arc(centerX - grinW/3, offsetM + 8, 3, 0, Math.PI*2); ctx.fill(); // Drip
    } else if (state.victoryString !== "") {
      const mouthScale = p.isDucking ? 0.8 : 1.2;
      ctx.fillStyle = '#100'; ctx.beginPath();
      ctx.ellipse(centerX, eyeY + mouthYOffset, 22 * mouthScale, 14 * mouthScale, 0, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = 'white'; ctx.lineWidth = 2;
      for(let i=-3; i<=3; i++) {
        ctx.beginPath(); ctx.moveTo(centerX + i * (6 * mouthScale), eyeY + mouthYOffset - (10 * mouthScale));
        ctx.lineTo(centerX + i * (6 * mouthScale), eyeY + mouthYOffset + (10 * mouthScale)); ctx.stroke();
      }
    } else if (p.invincibilityTimer > 15) {
      ctx.beginPath(); ctx.strokeStyle = 'black'; ctx.lineWidth = 3;
      ctx.moveTo(centerX - 10, eyeY + mouthYOffset);
      ctx.quadraticCurveTo(centerX, eyeY + mouthYOffset - 8, centerX + 10, eyeY + mouthYOffset); ctx.stroke();
    } else if (p.pushbackTimer > 0) {
      ctx.beginPath(); ctx.fillStyle = 'black';
      ctx.arc(centerX, eyeY + mouthYOffset, 8 * (p.isDucking ? 0.6 : 1.0), 0, Math.PI * 2); ctx.fill();
    } else if (p.killSatisfactionTimer > 0) {
      // --- RUGGED MANIACAL GRIN FOR KILL SATISFACTION ---
      const grinW = 32, grinH = 14;
      ctx.fillStyle = 'black'; // Pure black interior for a "void" look
      ctx.fillRect(centerX - grinW/2, eyeY + mouthYOffset - grinH/2, grinW, grinH);
      ctx.strokeStyle = 'white'; ctx.lineWidth = 2;
      // Teeth Block (solid white strips)
      ctx.fillStyle = 'white';
      ctx.fillRect(centerX - grinW/2.2, eyeY + mouthYOffset - grinH/3, grinW/1.1, grinH/1.5);
      // Vertical tooth separators
      ctx.strokeStyle = 'black'; ctx.lineWidth = 1;
      for(let i=-2; i<=2; i++) {
        ctx.beginPath(); ctx.moveTo(centerX + i * 5, eyeY + mouthYOffset - grinH/3); ctx.lineTo(centerX + i * 5, eyeY + mouthYOffset + grinH/3); ctx.stroke();
      }
      // Rectangular outline
      ctx.strokeStyle = 'black'; ctx.lineWidth = 2;
      ctx.strokeRect(centerX - grinW/2, eyeY + mouthYOffset - grinH/2, grinW, grinH);
    } else if (gameStateRef.current.playerStunTimer > 0) {
      ctx.beginPath(); ctx.strokeStyle = 'black'; ctx.lineWidth = 2;
      for (let i = -10; i <= 10; i++) {
        const mx = centerX + i;
        const my = eyeY + mouthYOffset + Math.sin(i * 0.5 + state.frame * 0.2) * 3;
        if (i === -10) ctx.moveTo(mx, my); else ctx.lineTo(mx, my);
      }
      ctx.stroke();
    } else { 
      // Default scowl
      ctx.beginPath(); ctx.strokeStyle = 'black'; ctx.lineWidth = 3;
      ctx.moveTo(centerX - 8, eyeY + mouthYOffset);
      ctx.lineTo(centerX + 8, eyeY + mouthYOffset);
      ctx.stroke();
    }
    ctx.restore();

    // Weapon
    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14, gunY = p.isDucking ? drawY + 10 : drawY + 25;
    if (!isFlashing) {
        if (currentWeapon === 'GUN') { ctx.fillStyle = '#333'; ctx.fillRect(gunX, gunY, 24, 10); } 
        else if (currentWeapon === 'BOULDER') { ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(gunX + 12, gunY + 5, 12, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); }
        else if (currentWeapon === 'SHOTGUN') { ctx.fillStyle = '#00FFFF'; ctx.fillRect(gunX, gunY, 20, 12); }
        else if (currentWeapon === 'FLAMETHROWER') { ctx.fillStyle = '#444'; ctx.fillRect(gunX, gunY, 30, 14); ctx.fillStyle = '#FF4500'; ctx.fillRect(p.facing === 1 ? gunX + 30 : gunX - 5, gunY + 4, 5, 6); }
        else if (currentWeapon === 'TSUNAMI') { ctx.fillStyle = '#1E90FF'; ctx.fillRect(gunX, gunY, 32, 16); ctx.fillStyle = '#fff'; ctx.fillRect(p.facing === 1 ? gunX + 28 : gunX, gunY + 4, 4, 8); }
    }
    ctx.restore();
  };

  const drawBossSprite = (ctx: CanvasRenderingContext2D, e: Enemy, id: string | null) => {
      const { pos, width, height } = e; ctx.save(); ctx.translate(pos.x, pos.y);
      if (e.rotation) {
          ctx.translate(width / 2, height / 2);
          ctx.rotate(e.rotation);
          ctx.translate(-width / 2, -height / 2);
      }
      switch (id) {
        case 'Artie Avalanche':
            ctx.fillStyle = '#AED6F1'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeStyle = 'black'; ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7);
            ctx.fillStyle = '#FF8A80'; // Flesh tone
            ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#2E86C1'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, Math.PI, 0); ctx.fill(); ctx.stroke(); break;
        case 'Victor Volcano':
            ctx.fillStyle = '#BA4A00'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7);
            ctx.fillStyle = '#C62828'; // Meaty tone
            ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.3, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#FF4500'; ctx.fillRect(width * 0.2, height * 0.2, width * 0.6, height * 0.1); break;
        case 'Ernie Earthquake':
            ctx.fillStyle = '#6E2C00'; ctx.fillRect(0, height * 0.3, width, height * 0.7); ctx.strokeRect(0, height * 0.3, width, height * 0.7);
            ctx.fillStyle = '#FF5252'; // Meaty tone
            ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); break;
        case 'Hector Hurricane':
            ctx.fillStyle = '#16A085'; ctx.fillRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.strokeRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7);
            ctx.fillStyle = '#FF8A80'; // Meaty tone
            ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); break;
        default: ctx.fillStyle = 'yellow'; ctx.fillRect(0, 0, width, height); break;
      }
      ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current; if (!canvas) return; const ctx = canvas.getContext('2d'); if (!ctx) return; const state = gameStateRef.current;
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) { ctx.fillStyle = 'black'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT); return; }
    const { player, enemies, projectiles, particles, blocks, camera, pickups, damageNumbers } = state;
    const colors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };
    ctx.fillStyle = colors.bg; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save(); 
    if (state.screenShakeTimer > 0) {
      ctx.translate((Math.random()-0.5)*15, (Math.random()-0.5)*15);
    }
    ctx.translate(-camera.x, -camera.y);
    blocks.forEach(b => { 
        if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); } 
        else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; } 
        else { ctx.fillStyle = colors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = colors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); } 
    });

    pickups.forEach(p => {
        if (p.type.includes('health')) { ctx.fillStyle = 'red'; const thick = p.type === 'large_health' ? 10 : 5; ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height); ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick); } 
        else { ctx.fillStyle = 'yellow'; const thick = p.type === 'large_ammo' ? 12 : 6; ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height); ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick); }
    });
    state.bossVolcanoTelegraphs.forEach(v => {
       ctx.save();
       ctx.globalCompositeOperation = 'screen';
       ctx.fillStyle = `rgba(255, 100, 0, ${0.3 + Math.sin(state.frame * 0.2) * 0.2})`;
       if (v.type === 'ground') {
           ctx.fillRect(v.pos.x - 40, v.pos.y - 10, 80, 40);
           ctx.strokeStyle = '#FF4500'; ctx.lineWidth = 2; ctx.strokeRect(v.pos.x - 40, v.pos.y - 10, 80, 40);
       } else {
           ctx.fillRect(v.pos.x - 10, v.pos.y - 40, 40, 80);
           ctx.strokeStyle = '#FF4500'; ctx.lineWidth = 2; ctx.strokeRect(v.pos.x - 10, v.pos.y - 40, 40, 80);
       }
       ctx.restore();
    });

    state.bossPoopTelegraphs.forEach(t => {
        ctx.save();
        const isSpawnLeft = t.spawnX === BOSS_DOOR_X;
        const iconX = isSpawnLeft ? BOSS_DOOR_X + 20 : 8000 - 40;
        const alpha = Math.abs(Math.sin(state.frame * 0.4));
        ctx.fillStyle = `rgba(139, 69, 19, ${alpha})`;
        ctx.font = 'bold 44px "Press Start 2P"';
        ctx.textAlign = 'center';
        ctx.fillText('!', iconX, t.pos.y + 10);
        ctx.strokeStyle = `rgba(255, 255, 255, ${alpha})`;
        ctx.lineWidth = 2;
        ctx.strokeText('!', iconX, t.pos.y + 10);
        ctx.restore();
    });

    state.bossVolcanoes.forEach(v => { 
        ctx.save(); 
        if (v.type === 'ground') {
            ctx.fillStyle = '#4A235A'; 
            ctx.beginPath();
            ctx.moveTo(v.pos.x - 25, v.pos.y + 10);
            ctx.lineTo(v.pos.x - 10, v.pos.y - 10);
            ctx.lineTo(v.pos.x + 10, v.pos.y - 10);
            ctx.lineTo(v.pos.x + 25, v.pos.y + 10);
            ctx.fill();
            ctx.strokeStyle = '#FF4500'; ctx.lineWidth = 2; ctx.stroke();
            ctx.fillStyle = '#FF4500'; ctx.fillRect(v.pos.x - 5, v.pos.y - 12, 10, 5);
        } else {
            const isLeftWall = v.pos.x < BOSS_DOOR_X + 400;
            ctx.fillStyle = '#5D6D7E';
            if (isLeftWall) {
                ctx.fillRect(BOSS_DOOR_X, v.pos.y - 18, 12, 36); 
                ctx.beginPath();
                ctx.moveTo(BOSS_DOOR_X + 12, v.pos.y - 12);
                ctx.lineTo(BOSS_DOOR_X + 42, v.pos.y - 8);
                ctx.lineTo(BOSS_DOOR_X + 42, v.pos.y + 8);
                ctx.lineTo(BOSS_DOOR_X + 12, v.pos.y + 12);
                ctx.fill();
                ctx.fillStyle = '#FF4500'; ctx.fillRect(BOSS_DOOR_X + 42, v.pos.y - 8, 4, 16);
            } else {
                ctx.fillRect(7988, v.pos.y - 18, 12, 36); 
                ctx.beginPath();
                ctx.moveTo(8000 - 12, v.pos.y - 12);
                ctx.lineTo(8000 - 42, v.pos.y - 8);
                ctx.lineTo(8000 - 42, v.pos.y + 8);
                ctx.lineTo(8000 - 12, v.pos.y + 12);
                ctx.fill();
                ctx.fillStyle = '#FF4500'; ctx.fillRect(8000 - 46, v.pos.y - 8, 4, 16);
            }
        }
        ctx.restore(); 
    });

    state.bossSteamExplosions.forEach(exp => {
        ctx.save();
        const alpha = Math.min(1.0, exp.life / 20);
        const gradient = ctx.createRadialGradient(exp.pos.x, exp.pos.y, 10, exp.pos.x, exp.pos.y, exp.radius);
        gradient.addColorStop(0, `rgba(255, 255, 255, ${0.7 * alpha})`);
        gradient.addColorStop(0.5, `rgba(178, 235, 242, ${0.4 * alpha})`);
        gradient.addColorStop(1, `rgba(255, 255, 255, 0)`);
        ctx.fillStyle = gradient;
        ctx.beginPath(); ctx.arc(exp.pos.x, exp.pos.y, exp.radius, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
    });

    enemies.forEach(e => {
      if (e.health <= 0 && !e.isBlownAway) return;
      ctx.save();
      if (e.isBlownAway) { ctx.translate(e.pos.x + e.width / 2, e.pos.y + e.height / 2); ctx.rotate(e.rotation || 0); ctx.translate(-(e.pos.x + e.width / 2), -(e.pos.y + e.height / 2)); } 
      else if (e.type === 'boss' && state.arenaLocked && e.hitCooldown && e.hitCooldown > 0 && Math.floor(state.frame / 5) % 2 === 0) { ctx.globalAlpha = 0.4; }
      if (e.type === 'boss') { 
        if (e.bossState === 'hurricane') {
          ctx.save();
          const centerX = e.pos.x + e.width/2;
          const centerY = e.pos.y + e.height/2;
          const forceDir = (e.pos.x + e.width/2 - (player.pos.x + player.width/2)) > 0 ? 1 : -1;
          ctx.save();
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
          ctx.lineWidth = 2;
          for (let i = 0; i < 15; i++) {
              const seed = (i * 123.456) % 1;
              const y = (seed * CANVAS_HEIGHT);
              const speed = 15 + seed * 20;
              const offset = (state.frame * speed * forceDir) % (CANVAS_WIDTH * 2);
              const xStart = camera.x + (forceDir > 0 ? -CANVAS_WIDTH + offset : CANVAS_WIDTH + offset);
              ctx.beginPath();
              ctx.moveTo(xStart, y);
              ctx.lineTo(xStart + 80 * forceDir, y);
              ctx.stroke();
          }
          ctx.restore();
          const gradient = ctx.createRadialGradient(centerX, centerY, 50, centerX, centerY, 300);
          gradient.addColorStop(0, 'rgba(100, 100, 150, 0.4)');
          gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
          ctx.fillStyle = gradient;
          ctx.beginPath(); ctx.arc(centerX, centerY, 300, 0, Math.PI * 2); ctx.fill();
          ctx.strokeStyle = 'rgba(174, 214, 241, 0.6)';
          ctx.lineWidth = 1.5;
          for(let i=0; i<30; i++) {
             const rx = (Math.random()-0.5)*600;
             const ry = (Math.random()-0.5)*600;
             if (Math.sqrt(rx*rx + ry*ry) < 300) {
               ctx.beginPath(); ctx.moveTo(centerX + rx, centerY + ry); ctx.lineTo(centerX + rx - 5, centerY + ry + 15); ctx.stroke();
             }
          }
          ctx.restore();
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)'; ctx.lineWidth = 3;
          for(let i=0; i<6; i++) {
             ctx.beginPath(); const rot = (state.frame * 0.15) + (i * Math.PI * 0.33);
             ctx.arc(centerX, centerY, 80 + i * 35, rot, rot + 1.2); ctx.stroke();
          }
        }
        drawBossSprite(ctx, e, stageId); 
        const introTaunt = (status === GameStatus.BOSS_INTRO && bossTauntText) ? bossTauntText : null;
        const currentTaunt = introTaunt || (state.bossVulgarityTimer > 0 ? state.bossLastVulgarity : null);
        if (currentTaunt) {
          ctx.save(); ctx.font = 'bold 12px "Press Start 2P"'; ctx.fillStyle = 'white';
          ctx.shadowColor = 'black'; ctx.shadowBlur = 6; ctx.textAlign = 'center';
          ctx.fillText(currentTaunt, e.pos.x + e.width / 2, e.pos.y - 30); ctx.restore();
        }
      } 
      else { 
        if (e.enemyType === 'shield') { 
          ctx.fillStyle = '#444'; ctx.fillRect(e.pos.x + 10, e.pos.y, e.width - 10, e.height);
          if (e.isShieldActive) {
            ctx.fillStyle = '#2C3E50'; ctx.fillRect(e.pos.x, e.pos.y - 5, 15, e.height + 10);
            ctx.strokeStyle = '#00FFFF'; ctx.lineWidth = 2; ctx.strokeRect(e.pos.x, e.pos.y - 5, 15, e.height + 10);
          } else {
            ctx.fillStyle = '#7F8C8D'; ctx.fillRect(e.pos.x + 5, e.pos.y + 10, 10, e.height - 20);
          }
        } else if (e.id.startsWith('rusher')) {
          ctx.fillStyle = '#9B59B6'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
        } else if (e.enemyType === 'flyer' && e.width > 60) {
            ctx.fillStyle = '#34495E'; ctx.fillRect(e.pos.x, e.pos.y + 15, e.width, e.height - 30); 
        } else { 
          ctx.fillStyle = e.enemyType === 'flyer' ? COLORS.ENEMY_FLYER : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK); 
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); 
        } 
      }
      if (e.frozenTimer && e.frozenTimer > 0) { ctx.fillStyle = 'rgba(0, 255, 255, 0.4)'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10); }
      if (!e.isBlownAway) { ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5); }
      ctx.restore();
    });
    if (status !== GameStatus.LEVEL_INTRO || gameStateRef.current.introTimer >= 80) {
      drawPlayer(ctx, player);
      if (state.playerLastVulgarity && state.playerVulgarityTimer > 0) {
        ctx.save(); ctx.font = 'bold 10px "Press Start 2P"'; ctx.fillStyle = 'white';
        ctx.shadowColor = 'black'; ctx.shadowBlur = 4; ctx.textAlign = 'center';
        ctx.fillText(state.playerLastVulgarity, player.pos.x + player.width / 2, player.pos.y - 20); ctx.restore();
      }
    }
    projectiles.forEach(p => { 
        if (p.isBoulder) { 
            ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.pos.x * 0.05); 
            ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(0, 0, p.width/2, 0, Math.PI * 2); ctx.fill(); ctx.strokeStyle = 'black'; ctx.stroke(); ctx.restore(); 
        } else if (p.isShrapnel) {
            ctx.fillStyle = '#757575'; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); ctx.strokeStyle = 'black'; ctx.strokeRect(p.pos.x, p.pos.y, p.width, p.height);
        } else if (p.isPoop) {
            ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(state.frame * 0.45);
            ctx.fillStyle = '#5D4037'; ctx.beginPath(); const r = p.height / 2; ctx.moveTo(-p.width/2 + r, -p.height/2); ctx.lineTo(p.width/2 - r, -p.height/2); ctx.arc(p.width/2 - r, 0, r, -Math.PI/2, Math.PI/2); ctx.lineTo(-p.width/2 + r, p.height/2); ctx.arc(-p.width/2 + r, 0, r, Math.PI/2, -Math.PI/2); ctx.fill(); ctx.strokeStyle = '#3E2723'; ctx.lineWidth = 2.5; ctx.stroke();
            ctx.fillStyle = '#FFEB3B'; ctx.fillRect(-p.width/3.5, -p.height/5, 4, 4); ctx.fillRect(p.width/8, p.height/4, 3, 3); ctx.fillRect(p.width/4, -p.height/6, 3, 3); ctx.restore();
        } else { 
            ctx.fillStyle = (p.isIce) ? COLORS.PROJECTILE_ICE : (p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY); 
            ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); 
        } 
    });
    particles.forEach(p => { 
      ctx.save();
      if (!p.isStuck) { ctx.globalAlpha = p.life < 100 ? p.life / 100 : 1; } 
      else { ctx.globalAlpha = 0.85; }
      ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); ctx.restore();
    });
    damageNumbers.forEach(d => {
      ctx.save(); const alpha = d.life / d.maxLife; ctx.globalAlpha = alpha;
      ctx.font = `bold ${d.isCritical ? '24px' : '16px'} "Press Start 2P"`;
      ctx.fillStyle = d.isCritical ? '#FFD700' : (d.value > 50 ? '#FF4500' : '#FFFFFF');
      ctx.textAlign = 'center'; ctx.fillText(d.value.toString(), d.pos.x, d.pos.y); ctx.restore();
    });
    ctx.restore();
    if (state.victoryString && (status === GameStatus.PLAYING || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.VICTORY)) { 
      ctx.save(); ctx.font = 'bold 50px "Press Start 2P"'; ctx.fillStyle = 'yellow'; ctx.textAlign = 'center'; 
      ctx.strokeStyle = 'black'; ctx.lineWidth = 4; ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
      ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore();
    }
    if (state.deathTimer > 0) { 
      ctx.save(); ctx.font = 'bold 60px "Press Start 2P"'; ctx.fillStyle = '#FF0000'; ctx.textAlign = 'center'; 
      ctx.fillText(state.deathString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore();
    }
  }, [status, stageId, onPlayerUpdate, currentWeapon, invincibilityEnabled, jumpToBossEnabled, bossTauntText]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) {
      if (gameStateRef.current.frame === 0 && status === GameStatus.LEVEL_INTRO) {
        gameStateRef.current.victoryString = ""; gameStateRef.current.postVictoryTimer = 0;
        gameStateRef.current.bossExplosionTimer = 0; gameStateRef.current.introTimer = 0;
        gameStateRef.current.particles = []; gameStateRef.current.projectiles = [];
        gameStateRef.current.pickups = []; gameStateRef.current.enemies = []; 
        gameStateRef.current.damageNumbers = []; gameStateRef.current.camera = { x: 0, y: 0 };
        gameStateRef.current.player.health = INITIAL_PLAYER_HEALTH;
        gameStateRef.current.player.killSatisfactionTimer = 0;
        gameStateRef.current.player.bossKillSatisfactionTimer = 0;
        gameStateRef.current.player.invincibilityTimer = 0;
        gameStateRef.current.player.pushbackTimer = 0;
        gameStateRef.current.player.isCharging = false;
        gameStateRef.current.player.isUppercutting = false;
        gameStateRef.current.playerStunTimer = 0;
        createLevel(); gameStateRef.current.frame = 1;
      }
      frameId = window.requestAnimationFrame(loop);
    } else { 
      gameStateRef.current.victoryString = ""; gameStateRef.current.postVictoryTimer = 0;
      gameStateRef.current.bossExplosionTimer = 0; gameStateRef.current.introTimer = 0;
      gameStateRef.current.enemies = []; gameStateRef.current.particles = [];
      gameStateRef.current.projectiles = []; gameStateRef.current.camera = { x: 0, y: 0 };
      gameStateRef.current.playerLastVulgarity = ""; gameStateRef.current.playerVulgarityTimer = 0;
      gameStateRef.current.bossLastVulgarity = ""; gameStateRef.current.bossVulgarityTimer = 0;
      // Thorough reset for returning to menu
      gameStateRef.current.bossVolcanoes = [];
      gameStateRef.current.bossVolcanoTelegraphs = [];
      gameStateRef.current.bossPoopTelegraphs = [];
      gameStateRef.current.bossSteamExplosions = [];
      gameStateRef.current.victorWallSide = 0;
      gameStateRef.current.tsunamiActive = false;
      draw(); gameStateRef.current.frame = 0; 
    }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel, initialAmmo, jumpToBossEnabled]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

