import { GoogleGenAI } from "@google/genai";

export async function generateBriefing(): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: "Write a short, aggressive, meathead-style mission briefing for a hero who just wants to lift and destroy robots. Use gym slang.",
    });
    return response.text.trim();
  } catch (error) {
    return "YOUR MISSION IS TO DELETE WEAKNESS. REPS FOR THE DEAD.";
  }
}

export async function generateBossTaunt(bossName: string): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Write a one-sentence aggressive insult for a boss named ${bossName} to say to Meathead.`,
    });
    return response.text.trim();
  } catch (error) {
    return "YOU LOOK LIKE YOU SKIP LEG DAY!";
  }
}

