interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (h: number, sc: number, st: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => void;
  onBossEncounter: () => void;
  onBossTransition: () => void;
  onBossDefeated: (stageId: string) => void;
  onBossDeath: () => void;
  onGameOver: (victory: boolean) => void;
  onIntroComplete: () => void;
  onTogglePause: () => void;
  currentWeapon: WeaponType;
  initialAmmo: Record<WeaponType, number>;
  invincibilityEnabled: boolean;
  infiniteAmmoEnabled: boolean;
  jumpToBossEnabled: boolean;
  bossTauntText: string;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  status, stageId, onPlayerUpdate, onBossEncounter, onBossTransition, onBossDefeated, onBossDeath, onGameOver, onIntroComplete, onTogglePause, 
  currentWeapon, initialAmmo, invincibilityEnabled, infiniteAmmoEnabled, jumpToBossEnabled, bossTauntText 
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameStateRef = useRef({
    player: {
      id: 'player', pos: { x: 150, y: 400 }, vel: { x: 0, y: 0 }, width: 44, height: 64, health: INITIAL_PLAYER_HEALTH, maxHealth: INITIAL_PLAYER_HEALTH, type: 'player',
      isCharging: false, isUppercutting: false, isDucking: false, specialCharges: MAX_SPECIAL_CHARGES, specialChargeTimer: 0, chargeDuration: 0,
      isJumping: false, isGrounded: false, facing: 1, shootCooldown: 0, jumpPrepTimer: 0, landTimer: 0, invincibilityTimer: 0, pushbackTimer: 0,
      killSatisfactionTimer: 0, bossKillSatisfactionTimer: 0, hasUsedAirMove: false, jumpInputReleased: true, chargeInputReleased: true,
      currentWeapon: 'GUN', availableWeapons: ['GUN'], weaponAmmo: { ...initialAmmo }
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    particles: [] as Particle[],
    damageNumbers: [] as DamageNumber[],
    camera: { x: 0, y: 0 },
    frame: 0,
    deathTimer: 0,
    introTimer: 0,
    victoryString: "",
    arenaLocked: false,
  });

  const keys = useRef<Record<string, boolean>>({});

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => keys.current[e.key.toLowerCase()] = true;
    const handleKeyUp = (e: KeyboardEvent) => keys.current[e.key.toLowerCase()] = false;
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    state.enemies = [];
    for (let i = 0; i < 15; i++) {
      state.enemies.push({
        id: `e-${i}`, pos: { x: 800 + i * 500, y: 480 }, vel: { x: -1, y: 0 }, width: 40, height: 40, health: 50, maxHealth: 50, type: 'enemy',
        enemyType: 'tank', behavior: 'patrol', patrolRange: 200, initialX: 800 + i * 500, shootTimer: 0
      });
    }
  }, []);

  const update = useCallback(() => {
    const state = gameStateRef.current;
    if (status !== GameStatus.PLAYING) return;

    state.frame++;
    const { player, enemies, projectiles } = state;
    const k = keys.current;

    // --- Inputs ---
    const moveLeft = k['a'] || k['arrowleft'];
    const moveRight = k['d'] || k['arrowright'];
    const jumpPressed = k[' '] || k['w'] || k['arrowup'];
    const specialPressed = k['shift'];

    // --- Physics & Logic ---
    if (player.pushbackTimer > 0) {
      player.pushbackTimer--;
    } else if (player.isCharging) {
      player.vel.x = player.facing * CHARGE_SPEED;
      player.chargeDuration--;
      if (player.chargeDuration <= 0) player.isCharging = false;

      // ALLOW JUMPING MID-CHARGE
      if (jumpPressed && player.isGrounded && player.jumpInputReleased) {
        player.isCharging = false; // VULNERABLE NOW
        player.vel.y = PLAYER_JUMP_FORCE;
        player.isGrounded = false;
        player.jumpInputReleased = false;
      }
    } else {
      // Normal Movement
      if (moveLeft) {
        player.vel.x = -PLAYER_SPEED;
        player.facing = -1;
      } else if (moveRight) {
        player.vel.x = PLAYER_SPEED;
        player.facing = 1;
      } else {
        if (player.isGrounded) player.vel.x = 0;
      }

      // Jump
      if (jumpPressed && player.isGrounded && player.jumpInputReleased) {
        player.vel.y = PLAYER_JUMP_FORCE;
        player.isGrounded = false;
        player.jumpInputReleased = false;
      }

      // Start Charge
      if (specialPressed && player.chargeInputReleased && player.specialCharges > 0 && player.isGrounded) {
        player.isCharging = true;
        player.chargeDuration = CHARGE_DURATION;
        player.specialCharges--;
        player.chargeInputReleased = false;
      }
    }

    if (!jumpPressed) player.jumpInputReleased = true;
    if (!specialPressed) player.chargeInputReleased = true;

    // Air Physics: Bleed off momentum if over max speed
    if (!player.isGrounded) {
      player.vel.y += GRAVITY;
      if (Math.abs(player.vel.x) > PLAYER_SPEED) {
        player.vel.x *= 0.98; // Bleed off the charge boost
      } else {
        player.vel.x *= FRICTION;
      }
    }

    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    // Simple Ground Check
    const groundY = CANVAS_HEIGHT - 100;
    if (player.pos.y + player.height > groundY) {
      player.pos.y = groundY - player.height;
      player.vel.y = 0;
      player.isGrounded = true;
    }

    // Camera
    state.camera.x = Math.max(state.camera.x, player.pos.x - 300);

    // Update HUD
    onPlayerUpdate(player.health, player.specialCharges, player.specialChargeTimer, player.weaponAmmo);
  }, [status, onPlayerUpdate]);

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (!ctx) return;
    const state = gameStateRef.current;
    const { player, camera } = state;

    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    ctx.save();
    ctx.translate(-camera.x, 0);

    // Ground
    ctx.fillStyle = '#333';
    ctx.fillRect(0, CANVAS_HEIGHT - 100, 10000, 100);

    // Player
    ctx.fillStyle = player.isCharging ? COLORS.MEATHEAD_GLOW : COLORS.MEATHEAD_SKIN;
    ctx.fillRect(player.pos.x, player.pos.y, player.width, player.height);

    // Face rendering
    const centerX = player.pos.x + player.width / 2;
    const eyeY = player.pos.y + 15;
    ctx.fillStyle = 'black';
    ctx.beginPath();
    ctx.arc(centerX - 8, eyeY, 3, 0, Math.PI * 2);
    ctx.arc(centerX + 8, eyeY, 3, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }, []);

  useEffect(() => {
    let raf: number;
    const loop = () => { update(); draw(); raf = requestAnimationFrame(loop); };
    if (status === GameStatus.LEVEL_INTRO) createLevel();
    loop();
    return () => cancelAnimationFrame(raf);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

