    });

    state.bossVolcanoes.forEach(v => { 
        ctx.save(); 
        if (v.type === 'ground') {
            ctx.fillStyle = '#4A235A'; 
            ctx.beginPath();
            ctx.moveTo(v.pos.x - 25, v.pos.y + 10);
            ctx.lineTo(v.pos.x - 10, v.pos.y - 10);
            ctx.lineTo(v.pos.x + 10, v.pos.y - 10);
            ctx.lineTo(v.pos.x + 25, v.pos.y + 10);
            ctx.fill();
            ctx.strokeStyle = '#FF4500'; ctx.lineWidth = 2; ctx.stroke();
            ctx.fillStyle = '#FF4500'; ctx.fillRect(v.pos.x - 5, v.pos.y - 12, 10, 5);
        } else {
            const isLeftWall = v.pos.x < BOSS_DOOR_X + 400;
            ctx.fillStyle = '#5D6D7E';
            if (isLeftWall) {
                ctx.fillRect(BOSS_DOOR_X, v.pos.y - 18, 12, 36); 
                ctx.beginPath();
                ctx.moveTo(BOSS_DOOR_X + 12, v.pos.y - 12);
                ctx.lineTo(BOSS_DOOR_X + 42, v.pos.y - 8);
                ctx.lineTo(BOSS_DOOR_X + 42, v.pos.y + 8);
                ctx.lineTo(BOSS_DOOR_X + 12, v.pos.y + 12);
                ctx.fill();
                ctx.fillStyle = '#FF4500'; ctx.fillRect(BOSS_DOOR_X + 42, v.pos.y - 8, 4, 16);
            } else {
                ctx.fillRect(7988, v.pos.y - 18, 12, 36); 
                ctx.beginPath();
                ctx.moveTo(8000 - 12, v.pos.y - 12);
                ctx.lineTo(8000 - 42, v.pos.y - 8);
                ctx.lineTo(8000 - 42, v.pos.y + 8);
                ctx.lineTo(8000 - 12, v.pos.y + 12);
                ctx.fill();
                ctx.fillStyle = '#FF4500'; ctx.fillRect(8000 - 46, v.pos.y - 8, 4, 16);
            }
        }
        ctx.restore(); 
    });

    state.bossSteamExplosions.forEach(exp => {
        ctx.save();
        const alpha = Math.min(1.0, exp.life / 20);
        const gradient = ctx.createRadialGradient(exp.pos.x, exp.pos.y, 10, exp.pos.x, exp.pos.y, exp.radius);
        gradient.addColorStop(0, `rgba(255, 255, 255, ${0.7 * alpha})`);
        gradient.addColorStop(0.5, `rgba(178, 235, 242, ${0.4 * alpha})`);
        gradient.addColorStop(1, `rgba(255, 255, 255, 0)`);
        ctx.fillStyle = gradient;
        ctx.beginPath(); ctx.arc(exp.pos.x, exp.pos.y, exp.radius, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
    });

    enemies.forEach(e => {
      if (e.health <= 0 && !e.isBlownAway) return;
      ctx.save();
      if (e.isBlownAway) { ctx.translate(e.pos.x + e.width / 2, e.pos.y + e.height / 2); ctx.rotate(e.rotation || 0); ctx.translate(-(e.pos.x + e.width / 2), -(e.pos.y + e.height / 2)); } 
      else if (e.type === 'boss' && state.arenaLocked && e.hitCooldown && e.hitCooldown > 0 && Math.floor(state.frame / 5) % 2 === 0) { ctx.globalAlpha = 0.4; }
      if (e.type === 'boss') { 
        if (e.bossState === 'hurricane') {
          ctx.save();
          const centerX = e.pos.x + e.width/2;
          const centerY = e.pos.y + e.height/2;
          const forceDir = (e.pos.x + e.width/2 - (player.pos.x + player.width/2)) > 0 ? 1 : -1;
          ctx.save();
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
          ctx.lineWidth = 2;
          for (let i = 0; i < 15; i++) {
              const seed = (i * 123.456) % 1;
              const y = (seed * CANVAS_HEIGHT);
              const speed = 15 + seed * 20;
              const offset = (state.frame * speed * forceDir) % (CANVAS_WIDTH * 2);
              const xStart = camera.x + (forceDir > 0 ? -CANVAS_WIDTH + offset : CANVAS_WIDTH + offset);
              ctx.beginPath();
              ctx.moveTo(xStart, y);
              ctx.lineTo(xStart + 80 * forceDir, y);
              ctx.stroke();
          }
          ctx.restore();
          const gradient = ctx.createRadialGradient(centerX, centerY, 50, centerX, centerY, 300);
          gradient.addColorStop(0, 'rgba(100, 100, 150, 0.4)');
          gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
          ctx.fillStyle = gradient;
          ctx.beginPath(); ctx.arc(centerX, centerY, 300, 0, Math.PI * 2); ctx.fill();
          ctx.strokeStyle = 'rgba(174, 214, 241, 0.6)';
          ctx.lineWidth = 1.5;
          for(let i=0; i<30; i++) {
             const rx = (Math.random()-0.5)*600;
             const ry = (Math.random()-0.5)*600;
             if (Math.sqrt(rx*rx + ry*ry) < 300) {
               ctx.beginPath(); ctx.moveTo(centerX + rx, centerY + ry); ctx.lineTo(centerX + rx - 5, centerY + ry + 15); ctx.stroke();
             }
          }
          ctx.restore();
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)'; ctx.lineWidth = 3;
          for(let i=0; i<6; i++) {
             ctx.beginPath(); const rot = (state.frame * 0.15) + (i * Math.PI * 0.33);
             ctx.arc(centerX, centerY, 80 + i * 35, rot, rot + 1.2); ctx.stroke();
          }
        }
        drawBossSprite(ctx, e, stageId); 
        const introTaunt = (status === GameStatus.BOSS_INTRO && bossTauntText) ? bossTauntText : null;
        const currentTaunt = introTaunt || (state.bossVulgarityTimer > 0 ? state.bossLastVulgarity : null);
        if (currentTaunt) {
          ctx.save(); ctx.font = 'bold 12px "Press Start 2P"'; ctx.fillStyle = 'white';
          ctx.shadowColor = 'black'; ctx.shadowBlur = 6; ctx.textAlign = 'center';
          ctx.fillText(currentTaunt, e.pos.x + e.width / 2, e.pos.y - 30); ctx.restore();
        }
      } 
      else { 
        if (e.enemyType === 'shield') { 
          ctx.fillStyle = '#444'; ctx.fillRect(e.pos.x + 10, e.pos.y, e.width - 10, e.height);
          if (e.isShieldActive) {
            ctx.fillStyle = '#2C3E50'; ctx.fillRect(e.pos.x, e.pos.y - 5, 15, e.height + 10);
            ctx.strokeStyle = '#00FFFF'; ctx.lineWidth = 2; ctx.strokeRect(e.pos.x, e.pos.y - 5, 15, e.height + 10);
          } else {
            ctx.fillStyle = '#7F8C8D'; ctx.fillRect(e.pos.x + 5, e.pos.y + 10, 10, e.height - 20);
          }
        } else if (e.id.startsWith('rusher')) {
          ctx.fillStyle = '#9B59B6'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
        } else if (e.enemyType === 'flyer' && e.width > 60) {
            ctx.fillStyle = '#34495E'; ctx.fillRect(e.pos.x, e.pos.y + 15, e.width, e.height - 30); 
        } else { 
          ctx.fillStyle = e.enemyType === 'flyer' ? COLORS.ENEMY_FLYER : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK); 
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); 
        } 
      }
      if (e.frozenTimer && e.frozenTimer > 0) { ctx.fillStyle = 'rgba(0, 255, 255, 0.4)'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10); }
      if (!e.isBlownAway) { ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5); }
      ctx.restore();
    });
    if (status !== GameStatus.LEVEL_INTRO || gameStateRef.current.introTimer >= 80) {
      drawPlayer(ctx, player);
      if (state.playerLastVulgarity && state.playerVulgarityTimer > 0) {
        ctx.save(); ctx.font = 'bold 10px "Press Start 2P"'; ctx.fillStyle = 'white';
        ctx.shadowColor = 'black'; ctx.shadowBlur = 4; ctx.textAlign = 'center';
        ctx.fillText(state.playerLastVulgarity, player.pos.x + player.width / 2, player.pos.y - 20); ctx.restore();
      }
    }
    projectiles.forEach(p => { 
        if (p.isBoulder) { 
            ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.pos.x * 0.05); 
            ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(0, 0, p.width/2, 0, Math.PI * 2); ctx.fill(); ctx.strokeStyle = 'black'; ctx.stroke(); ctx.restore(); 
        } else if (p.isShrapnel) {
            ctx.fillStyle = '#757575'; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); ctx.strokeStyle = 'black'; ctx.strokeRect(p.pos.x, p.pos.y, p.width, p.height);
        } else if (p.isPoop) {
            ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(state.frame * 0.45);
            ctx.fillStyle = '#5D4037'; ctx.beginPath(); const r = p.height / 2; ctx.moveTo(-p.width/2 + r, -p.height/2); ctx.lineTo(p.width/2 - r, -p.height/2); ctx.arc(p.width/2 - r, 0, r, -Math.PI/2, Math.PI/2); ctx.lineTo(-p.width/2 + r, p.height/2); ctx.arc(-p.width/2 + r, 0, r, Math.PI/2, -Math.PI/2); ctx.fill(); ctx.strokeStyle = '#3E2723'; ctx.lineWidth = 2.5; ctx.stroke();
            ctx.fillStyle = '#FFEB3B'; ctx.fillRect(-p.width/3.5, -p.height/5, 4, 4); ctx.fillRect(p.width/8, p.height/4, 3, 3); ctx.fillRect(p.width/4, -p.height/6, 3, 3); ctx.restore();
        } else { 
            ctx.fillStyle = (p.isIce) ? COLORS.PROJECTILE_ICE : (p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY); 
            ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); 
        } 
    });
    particles.forEach(p => { 
      ctx.save();
      if (!p.isStuck) { ctx.globalAlpha = p.life < 100 ? p.life / 100 : 1; } 
      else { ctx.globalAlpha = 0.85; }
      ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); ctx.restore();
    });
    damageNumbers.forEach(d => {
      ctx.save(); const alpha = d.life / d.maxLife; ctx.globalAlpha = alpha;
      ctx.font = `bold ${d.isCritical ? '24px' : '16px'} "Press Start 2P"`;
      ctx.fillStyle = d.isCritical ? '#FFD700' : (d.value > 50 ? '#FF4500' : '#FFFFFF');
      ctx.textAlign = 'center'; ctx.fillText(d.value.toString(), d.pos.x, d.pos.y); ctx.restore();
    });
    ctx.restore();
    if (state.victoryString && (status === GameStatus.PLAYING || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.VICTORY)) { 
      ctx.save(); ctx.font = 'bold 50px "Press Start 2P"'; ctx.fillStyle = 'yellow'; ctx.textAlign = 'center'; 
      ctx.strokeStyle = 'black'; ctx.lineWidth = 4; ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
      ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore();
    }
    if (state.deathTimer > 0) { 
      ctx.save(); ctx.font = 'bold 60px "Press Start 2P"'; ctx.fillStyle = '#FF0000'; ctx.textAlign = 'center'; 
      ctx.fillText(state.deathString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore();
    }
  }, [status, stageId, onPlayerUpdate, currentWeapon, invincibilityEnabled, jumpToBossEnabled, bossTauntText]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) {
      if (gameStateRef.current.frame === 0 && status === GameStatus.LEVEL_INTRO) {
        gameStateRef.current.victoryString = ""; gameStateRef.current.postVictoryTimer = 0;
        gameStateRef.current.bossExplosionTimer = 0; gameStateRef.current.introTimer = 0;
        gameStateRef.current.particles = []; gameStateRef.current.projectiles = [];
        gameStateRef.current.pickups = []; gameStateRef.current.enemies = []; 
        gameStateRef.current.damageNumbers = []; gameStateRef.current.camera = { x: 0, y: 0 };
        gameStateRef.current.player.health = INITIAL_PLAYER_HEALTH;
        gameStateRef.current.player.killSatisfactionTimer = 0;
        gameStateRef.current.player.bossKillSatisfactionTimer = 0;
        gameStateRef.current.player.invincibilityTimer = 0;
        gameStateRef.current.player.pushbackTimer = 0;
        gameStateRef.current.player.isCharging = false;
        gameStateRef.current.player.isUppercutting = false;
        gameStateRef.current.playerStunTimer = 0;
        createLevel(); gameStateRef.current.frame = 1;
      }
      frameId = window.requestAnimationFrame(loop);
    } else { 
      gameStateRef.current.victoryString = ""; gameStateRef.current.postVictoryTimer = 0;
      gameStateRef.current.bossExplosionTimer = 0; gameStateRef.current.introTimer = 0;
      gameStateRef.current.enemies = []; gameStateRef.current.particles = [];
      gameStateRef.current.projectiles = []; gameStateRef.current.camera = { x: 0, y: 0 };
      gameStateRef.current.playerLastVulgarity = ""; gameStateRef.current.playerVulgarityTimer = 0;
      gameStateRef.current.bossLastVulgarity = ""; gameStateRef.current.bossVulgarityTimer = 0;
      // Thorough reset for returning to menu
      gameStateRef.current.bossVolcanoes = [];
      gameStateRef.current.bossVolcanoTelegraphs = [];
      gameStateRef.current.bossPoopTelegraphs = [];
      gameStateRef.current.bossSteamExplosions = [];
      gameStateRef.current.victorWallSide = 0;
      gameStateRef.current.tsunamiActive = false;
      draw(); gameStateRef.current.frame = 0; 
    }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel, initialAmmo, jumpToBossEnabled]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import HUD from './components/HUD';
import Overlay from './components/Overlay';
import GameCanvas from './components/GameCanvas';
import { GameStatus, WeaponType } from './types';
import { INITIAL_PLAYER_HEALTH, SPECIAL_CHARGE_REGEN_FRAMES, MAX_AMMO } from './constants';

const STAGES = ['Artie Avalanche', 'Victor Volcano', 'Ernie Earthquake', 'Hector Hurricane'];

// --- DEV CONFIG ---
const SHOW_CHEATS = true;
// ------------------

const REBUKES = [
  "I ALREADY KILLED HIM, YOU DUMB FUCK.",
  "THAT SHIT-STAIN is ALREADY GONE.",
  "HE'S DEAD AS SHIT. QUIT WASTING MY GAINS.",
  "I ALREADY OBLITERATED THAT TRASH."
];

const LOCAL_BOSS_TAUNTS: Record<string, string[]> = {
  'Artie Avalanche': ["The cold will burn your face."],
  'Victor Volcano': ["Well done. That is how I will cook you."],
  'Ernie Earthquake': ["Are you ready to rumble, motherfucker?"],
  'Hector Hurricane': ["I'm gonna turn you into a soggy slab of shit."],
  'default': ["I'll break you in half!"]
};

const LOCAL_VICTORY_LINES: string[] = [
  "YOUR BIOLOGY WAS INFERIOR. THE PUMP PREVAILS.",
  "GAINS ACHIEVED. WEAKNESS DELETED.",
  "THAT WAS JUST A WARM-UP SET.",
  "IMAGINE BEING ORGANIC AND THIS WEAK.",
  "I'VE HAD TOUGHER WORKOUTS IN THE SAUNA.",
  "PURE BEEF BEATS METAL EVERY TIME."
];

const BOSS_WEAPON_MAP: Record<string, WeaponType> = {
  'Artie Avalanche': 'SHOTGUN',
  'Victor Volcano': 'FLAMETHROWER',
  'Ernie Earthquake': 'BOULDER',
  'Hector Hurricane': 'TSUNAMI'
};

const ALL_WEAPONS: WeaponType[] = ['GUN', 'BOULDER', 'SHOTGUN', 'FLAMETHROWER', 'TSUNAMI'];

const App: React.FC = () => {
  const [status, setStatus] = useState<GameStatus>(GameStatus.START);
  const [health, setHealth] = useState(INITIAL_PLAYER_HEALTH);
  const [specialCharges, setSpecialCharges] = useState(2);
  const [specialChargeTimer, setSpecialChargeTimer] = useState(0);
  const [bossTaunt, setBossTaunt] = useState("YOU'RE TOAST.");
  const [victorySpeech, setVictorySpeech] = useState("");
  const [briefing, setBriefing] = useState("Your mission is to kill everything in sight for no particular reason.");
  const [selectedStage, setSelectedStage] = useState<string | null>(null);
  const [defeatedStages, setDefeatedStages] = useState<string[]>([]);
  const [availableWeapons, setAvailableWeapons] = useState<WeaponType[]>(['GUN']);
  const [currentWeapon, setCurrentWeapon] = useState<WeaponType>('GUN');
  const [weaponAmmo, setWeaponAmmo] = useState<Record<WeaponType, number>>({
    'GUN': Infinity,
    'BOULDER': MAX_AMMO['BOULDER'],
    'SHOTGUN': MAX_AMMO['SHOTGUN'],
    'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
    'TSUNAMI': MAX_AMMO['TSUNAMI']
  });

  const [cheatEnabled, setCheatEnabled] = useState(false);
  const [invincibilityEnabled, setInvincibilityEnabled] = useState(false);
  const [infiniteAmmoEnabled, setInfiniteAmmoEnabled] = useState(false);
  const [infinitePowerEnabled, setInfinitePowerEnabled] = useState(false);
  const [jumpToBossEnabled, setJumpToBossEnabled] = useState(false);

  const [isVictoryPhase, setIsVictoryPhase] = useState(false);
  const [overlayActiveTime, setOverlayActiveTime] = useState(0);

  const [selectedIndex, setSelectedIndex] = useState(0);
  const lastPadInputRef = useRef(0);
  const lastAStateRef = useRef(false);
  const lastBStateRef = useRef(false);
  const lastStartStateRef = useRef(false);
  const lastLBStateRef = useRef(false);
  const lastRBStateRef = useRef(false);

  // Global Meathead cooldown for App-level speech
  const meatheadSpeechCooldownRef = useRef(0);

  useEffect(() => {
    let interval: number;
    if (status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.START || status === GameStatus.VICTORY) {
      setOverlayActiveTime(0);
      interval = window.setInterval(() => {
        setOverlayActiveTime(prev => prev + 100);
      }, 100);
    }
    return () => clearInterval(interval);
  }, [status]);

  // Handle Meathead speech cooldown decrement
  useEffect(() => {
    const timer = setInterval(() => {
      if (meatheadSpeechCooldownRef.current > 0) meatheadSpeechCooldownRef.current -= 100;
    }, 100);
    return () => clearInterval(timer);
  }, []);

  const speakBossTaunt = useCallback((stage: string, text: string) => {
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);
      switch (stage) {
        case 'Artie Avalanche':
          utterance.pitch = 1.6;
          utterance.rate = 0.85;
          break;
        case 'Victor Volcano':
          utterance.pitch = 0.7;
          utterance.rate = 0.85;
          break;
        case 'Ernie Earthquake':
          utterance.pitch = 0.1;
          utterance.rate = 0.55;
          break;
        case 'Hector Hurricane':
          utterance.pitch = 1.2;
          utterance.rate = 1.5;
          break;
        default:
          utterance.pitch = 1.0;
          utterance.rate = 1.0;
      }
      utterance.volume = 1.0;
      window.speechSynthesis.speak(utterance);
    }
  }, []);

  useEffect(() => {
    if (status === GameStatus.BOSS_INTRO && selectedStage && bossTaunt) {
      speakBossTaunt(selectedStage, bossTaunt);
    }
  }, [status, selectedStage, bossTaunt, speakBossTaunt]);

  const cycleWeapon = useCallback((dir: number) => {
    setAvailableWeapons(prevAvailable => {
      if (prevAvailable.length <= 1) return prevAvailable;
      setCurrentWeapon(current => {
        const idx = prevAvailable.indexOf(current);
        const nextIdx = (idx + dir + prevAvailable.length) % prevAvailable.length;
        return prevAvailable[nextIdx];
      });
      return prevAvailable;
    });
  }, []);

  const speakRebuke = useCallback(() => {
    if ('speechSynthesis' in window) {
      // RULE: Finish current line, 1s cooldown
      if (window.speechSynthesis.speaking) return;
      if (meatheadSpeechCooldownRef.current > 0) return;

      const text = REBUKES[Math.floor(Math.random() * REBUKES.length)];
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = 0.1;
      utterance.rate = 1.1;
      utterance.volume = 1.0;

      utterance.onend = () => {
        meatheadSpeechCooldownRef.current = 1000; // 1 second
      };
      utterance.onerror = () => {
        meatheadSpeechCooldownRef.current = 1000;
      };

      window.speechSynthesis.speak(utterance);
    }
  }, []);

  const togglePause = useCallback(() => {
    setStatus(prev => {
      if (isVictoryPhase || 
          prev === GameStatus.BOSS_TRANSITION || 
          prev === GameStatus.BOSS_INTRO || 
          prev === GameStatus.BOSS_VICTORY_SPEECH || 
          prev === GameStatus.LEVEL_INTRO ||
          prev === GameStatus.VICTORY) {
        return prev;
      }

      if (prev === GameStatus.PLAYING) {
        setSelectedIndex(0);
        return GameStatus.PAUSED;
      }
      if (prev === GameStatus.PAUSED) return GameStatus.PLAYING;
      return prev;
    });
  }, [isVictoryPhase]);

  const handleStart = useCallback(() => {
    if (overlayActiveTime < 2000) return;

    if (status === GameStatus.VICTORY || status === GameStatus.GAME_OVER) {
      setDefeatedStages([]);
      const weaponsToStart: WeaponType[] = (cheatEnabled && SHOW_CHEATS) ? ALL_WEAPONS : ['GUN'];
      setAvailableWeapons(weaponsToStart);
      setCurrentWeapon('GUN');
      setWeaponAmmo({
        'GUN': Infinity,
        'BOULDER': MAX_AMMO['BOULDER'],
        'SHOTGUN': MAX_AMMO['SHOTGUN'],
        'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
        'TSUNAMI': MAX_AMMO['TSUNAMI']
      });
      setSelectedIndex(0);
      setIsVictoryPhase(false);
      setStatus(GameStatus.START);
    } else if (status === GameStatus.START) {
      const weaponsToStart: WeaponType[] = (cheatEnabled && SHOW_CHEATS) ? ALL_WEAPONS : ['GUN'];
      setAvailableWeapons(weaponsToStart);
      setCurrentWeapon('GUN');
      setStatus(GameStatus.STAGE_SELECT);
    } else if (status === GameStatus.BOSS_INTRO) {
      setStatus(GameStatus.PLAYING);
    } else if (status === GameStatus.BOSS_VICTORY_SPEECH) {
      setIsVictoryPhase(false);
      if (defeatedStages.length >= 4) {
        setStatus(GameStatus.VICTORY);
      } else {
        setStatus(GameStatus.STAGE_SELECT);
        setSelectedStage(null);
        setSelectedIndex(0);
        setCurrentWeapon('GUN');
        setWeaponAmmo({
          'GUN': Infinity,
          'BOULDER': MAX_AMMO['BOULDER'],
          'SHOTGUN': MAX_AMMO['SHOTGUN'],
          'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
          'TSUNAMI': MAX_AMMO['TSUNAMI']
        });
      }
    }
  }, [status, defeatedStages, overlayActiveTime, cheatEnabled]);

  const handleResume = useCallback(() => {
    setStatus(GameStatus.PLAYING);
  }, []);

  const handleBossSelect = useCallback(() => {
    setSelectedStage(null);
    setSelectedIndex(0);
    setIsVictoryPhase(false);
    setCurrentWeapon('GUN');
    setStatus(GameStatus.STAGE_SELECT);
    setWeaponAmmo({
      'GUN': Infinity,
      'BOULDER': MAX_AMMO['BOULDER'],
      'SHOTGUN': MAX_AMMO['SHOTGUN'],
      'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
      'TSUNAMI': MAX_AMMO['TSUNAMI']
    });
  }, []);

  const handleQuitToMenu = useCallback(() => {
    setSelectedStage(null);
    setSelectedIndex(0);
    setIsVictoryPhase(false);
    setDefeatedStages([]);
    setCurrentWeapon('GUN');
    setStatus(GameStatus.START);
  }, []);

  const handleSelectStage = useCallback((stage: string) => {
    if (defeatedStages.includes(stage)) {
      speakRebuke();
      return;
    }
    setSelectedStage(stage);
    setHealth(INITIAL_PLAYER_HEALTH);
    setSpecialCharges(2);
    setSpecialChargeTimer(0);
    setCurrentWeapon('GUN');
    setWeaponAmmo({
      'GUN': Infinity,
      'BOULDER': MAX_AMMO['BOULDER'],
      'SHOTGUN': MAX_AMMO['SHOTGUN'],
      'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
      'TSUNAMI': MAX_AMMO['TSUNAMI']
    });
    setIsVictoryPhase(false);
    setStatus(GameStatus.LEVEL_INTRO);
  }, [defeatedStages, speakRebuke]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const key = e.key.toLowerCase();
      if (key === 'escape') {
        togglePause();
      }

      if (status === GameStatus.PAUSED || status === GameStatus.STAGE_SELECT) {
        if (key === 'arrowup' || key === 'w') {
          if (status === GameStatus.PAUSED) setSelectedIndex(p => (p - 1 + 3) % 3);
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p - 2 + 4) % 4);
        } else if (key === 'arrowdown' || key === 's') {
          if (status === GameStatus.PAUSED) setSelectedIndex(p => (p + 1) % 3);
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p + 2) % 4);
        } else if (key === 'arrowleft' || key === 'a') {
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p % 2 === 0 ? p + 1 : p - 1));
        } else if (key === 'arrowright' || key === 'd') {
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p % 2 === 0 ? p + 1 : p - 1));
        } else if (key === 'enter' || key === ' ') {
          if (status === GameStatus.PAUSED) {
            if (selectedIndex === 0) handleResume();
            else if (selectedIndex === 1) handleBossSelect();
            else if (selectedIndex === 2) handleQuitToMenu();
          } else if (status === GameStatus.STAGE_SELECT) {
            handleSelectStage(STAGES[selectedIndex]);
          }
        }
      } else if (status === GameStatus.PLAYING) {
        if (key === 'q') cycleWeapon(-1);
        if (key === 'e') cycleWeapon(1);
      } else if (status === GameStatus.START || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.VICTORY) {
        if (key === 'enter' || key === ' ') handleStart();
      }
    };
    const handleWheel = (e: WheelEvent) => {
      if (status === GameStatus.PLAYING) {
        cycleWeapon(e.deltaY > 0 ? 1 : -1);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('wheel', handleWheel);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('wheel', handleWheel);
    };
  }, [togglePause, status, cycleWeapon, selectedIndex, handleResume, handleBossSelect, handleQuitToMenu, handleSelectStage, handleStart]);

  const handleToggleCheat = useCallback(() => {
    setCheatEnabled(prev => !prev);
  }, []);

  const handleToggleInvincibility = useCallback(() => {
    setInvincibilityEnabled(prev => !prev);
  }, []);

  const handleToggleInfiniteAmmo = useCallback(() => {
    setInfiniteAmmoEnabled(prev => !prev);
  }, []);

  const handleToggleInfinitePower = useCallback(() => {
    setInfinitePowerEnabled(prev => !prev);
  }, []);

  const handleToggleJumpToBoss = useCallback(() => {
    setJumpToBossEnabled(prev => !prev);
  }, []);

  const handleBossTransition = useCallback(() => {
    setStatus(GameStatus.BOSS_TRANSITION);
  }, []);

  const handleBossDeath = useCallback(() => {
    setIsVictoryPhase(true);
  }, []);

  const handleBossEncounter = useCallback(() => {
    setStatus(GameStatus.BOSS_INTRO);
    const pool = LOCAL_BOSS_TAUNTS[selectedStage || ''] || LOCAL_BOSS_TAUNTS['default'];
    const taunt = pool[Math.floor(Math.random() * pool.length)];
    setBossTaunt(taunt);
  }, [selectedStage]);

  const handleBossDefeated = useCallback((stageId: string) => {
    const newWeapon = BOSS_WEAPON_MAP[stageId];
    if (newWeapon) {
      setAvailableWeapons(prev => {
        if (!prev.includes(newWeapon)) {
          return [...prev, newWeapon];
        }
        return prev;
      });
    }
    setDefeatedStages(prev => [...prev, stageId]);
    const speech = LOCAL_VICTORY_LINES[Math.floor(Math.random() * LOCAL_VICTORY_LINES.length)];
    setVictorySpeech(speech);
    setStatus(GameStatus.BOSS_VICTORY_SPEECH);
  }, []);

  const handleGameOver = useCallback((victory: boolean) => {
    if (!victory) {
        setIsVictoryPhase(false);
        setStatus(GameStatus.GAME_OVER);
    }
  }, []);

  const handlePlayerUpdate = useCallback((h: number, sc: number, st: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => {
    setHealth(h);
    setSpecialCharges(sc);
    setSpecialChargeTimer(st);
    if (ammo) setWeaponAmmo(ammo);
    if (forcedWeapon) setCurrentWeapon(forcedWeapon);
  }, []);

  const handleIntroComplete = useCallback(() => {
    setStatus(GameStatus.PLAYING);
  }, []);

  useEffect(() => {
    let frameId: number;
    const poll = () => {
      const gamepads = navigator.getGamepads();
      if (gamepads[0]) {
        const gp = gamepads[0];
        const now = Date.now();

        if (now - lastPadInputRef.current > 200) {
            let dx = 0; let dy = 0;
            if (gp.axes[0] < -0.5 || gp.buttons[14]?.pressed) dx = -1;
            if (gp.axes[0] > 0.5 || gp.buttons[15]?.pressed) dx = 1;
            if (gp.axes[1] < -0.5 || gp.buttons[12]?.pressed) dy = -1;
            if (gp.axes[1] > 0.5 || gp.buttons[13]?.pressed) dy = 1;

            if (status === GameStatus.STAGE_SELECT) {
              if (dx !== 0) {
                setSelectedIndex(prev => (prev % 2 === 0 ? prev + 1 : prev - 1));
                lastPadInputRef.current = now;
              }
              if (dy !== 0) {
                setSelectedIndex(prev => (prev < 2 ? prev + 2 : prev - 2));
                lastPadInputRef.current = now;
              }
            } else if (status === GameStatus.PAUSED) {
              if (dy < -0.5) { // Up
                  setSelectedIndex(prev => (prev - 1 + 3) % 3);
                  lastPadInputRef.current = now;
              } else if (dy > 0.5) { // Down
                  setSelectedIndex(prev => (prev + 1) % 3);
                  lastPadInputRef.current = now;
              }
            }
        }

        const aPressed = gp.buttons[0]?.pressed; 
        const bPressed = gp.buttons[1]?.pressed; 
        const startPressed = gp.buttons[9]?.pressed;
        const lbPressed = gp.buttons[4]?.pressed;
        const rbPressed = gp.buttons[5]?.pressed;

        if (aPressed && !lastAStateRef.current) {
            if (status === GameStatus.START || status === GameStatus.VICTORY || status === GameStatus.GAME_OVER || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH) {
              handleStart();
            } else if (status === GameStatus.STAGE_SELECT) {
              handleSelectStage(STAGES[selectedIndex]);
            } else if (status === GameStatus.PAUSED) {
              if (selectedIndex === 0) handleResume();
              else if (selectedIndex === 1) handleBossSelect();
              else handleQuitToMenu();
            }
        }

        if (bPressed && !lastBStateRef.current) {
            if (status === GameStatus.PAUSED) handleResume();
            else if (status === GameStatus.STAGE_SELECT) setStatus(GameStatus.START);
        }

        if (startPressed && !lastStartStateRef.current) {
            if (status === GameStatus.START) handleStart();
            else if (status === GameStatus.PLAYING || status === GameStatus.PAUSED) togglePause();
        }

        if (status === GameStatus.PLAYING) {
          if (lbPressed && !lastLBStateRef.current) cycleWeapon(-1);
          if (rbPressed && !lastRBStateRef.current) cycleWeapon(1);
        }

        lastAStateRef.current = !!aPressed;
        lastBStateRef.current = !!bPressed;
        lastStartStateRef.current = !!startPressed;
        lastLBStateRef.current = !!lbPressed;
        lastRBStateRef.current = !!rbPressed;
      }
      frameId = requestAnimationFrame(poll);
    };
    frameId = requestAnimationFrame(poll);
    return () => cancelAnimationFrame(frameId);
  }, [status, selectedIndex, handleStart, handleSelectStage, handleResume, handleBossSelect, handleQuitToMenu, togglePause, cycleWeapon]);

  return (
    <div className="relative w-screen h-screen flex items-center justify-center bg-black overflow-hidden">
      <div className="relative shadow-2xl border-4 border-gray-800 bg-[#121212]" style={{ width: 800, height: 600 }}>
        {(status === GameStatus.LEVEL_INTRO || status === GameStatus.PLAYING || status === GameStatus.BOSS_TRANSITION || status === GameStatus.PAUSED || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH) && (
          <HUD 
            health={health} 
            maxHealth={INITIAL_PLAYER_HEALTH} 
            specialCharges={specialCharges}
            specialChargeTimer={specialChargeTimer}
            maxChargeTimer={SPECIAL_CHARGE_REGEN_FRAMES}
            currentWeapon={currentWeapon}
            ammo={weaponAmmo[currentWeapon]}
            maxAmmo={MAX_AMMO[currentWeapon]}
          />
        )}

        <Overlay 
          status={status} 
          onStart={handleStart} 
          onResume={handleResume}
          onBossSelect={handleBossSelect}
          onQuitToMenu={handleQuitToMenu}
          onSelectStage={handleSelectStage}
          onCheatAllWeapons={handleToggleCheat}
          onToggleInvincibility={handleToggleInvincibility}
          onToggleInfiniteAmmo={handleToggleInfiniteAmmo}
          onToggleInfinitePower={handleToggleInfinitePower}
          onToggleJumpToBoss={handleToggleJumpToBoss}
          cheatEnabled={cheatEnabled}
          invincibilityEnabled={invincibilityEnabled}
          infiniteAmmoEnabled={infiniteAmmoEnabled}
          infinitePowerEnabled={infinitePowerEnabled}
          jumpToBossEnabled={jumpToBossEnabled}
          showCheats={SHOW_CHEATS}
          bossTaunt={bossTaunt}
          victorySpeech={victorySpeech}
          briefing={briefing}
          defeatedStages={defeatedStages}
          selectedIndex={selectedIndex}
          overlayActiveTime={overlayActiveTime}
          stageId={selectedStage}
        />

        <GameCanvas 
          status={status}
          stageId={selectedStage}
          onPlayerUpdate={handlePlayerUpdate}
          onBossEncounter={handleBossEncounter}
          onBossTransition={handleBossTransition}
          onBossDefeated={handleBossDefeated}
          onBossDeath={handleBossDeath}
          onGameOver={handleGameOver}
          onIntroComplete={handleIntroComplete}
          onTogglePause={togglePause}
          currentWeapon={currentWeapon}
          initialAmmo={weaponAmmo}
          invincibilityEnabled={invincibilityEnabled && (SHOW_CHEATS)}
          infiniteAmmoEnabled={infiniteAmmoEnabled && (SHOW_CHEATS)}
          infinitePowerEnabled={infinitePowerEnabled && (SHOW_CHEATS)}
          jumpToBossEnabled={jumpToBossEnabled && (SHOW_CHEATS)}
          bossTauntText={bossTaunt}
        />
      </div>
    </div>
  );
};

export default App;

