            <h1 className="text-4xl md:text-5xl text-red-600 mb-2 font-black tracking-tighter drop-shadow-[4px_4px_0px_white]">MEATHEAD</h1>
            <div className="text-white text-[9px] mb-6 border-y border-red-900 py-3 px-4 italic uppercase tracking-tight Chaudhary leading-relaxed max-w-sm mx-auto">
