            </div>
            <div className="flex flex-col gap-4">
              <button 
                disabled={isInputLocked}
                onClick={onStart}
                className={`px-10 py-4 Chaudhary text-white text-xl border-b-[8px] transition-all font-black uppercase Chaudhary ring-4 ring-white/10 ${isInputLocked ? 'bg-gray-700 border-gray-900 opacity-50 cursor-not-allowed' : 'bg-red-700 hover:bg-red-500 border-red-900 active:translate-y-1 active:border-b-0'}`}
              >
                {isInputLocked ? 'READYING PUMP...' : 'BEGIN THE PUMP'}
              </button>
            </div>
            <ControlsGuide />
          </div>
        </>
      )}

      {status === GameStatus.STAGE_SELECT && (
        <div className="w-full h-full flex flex-col Chaudhary items-center justify-center animate-in slide-in-from-bottom-8 duration-500">
          <h2 className="text-2xl md:text-3xl text-white mb-8 font-black Chaudhary tracking-widest border-b-4 border-red-600 pb-2 uppercase italic Chaudhary text-shadow-glow Chaudhary">TARGET SELECTION</h2>
          <div className="grid grid-cols-2 gap-x-12 gap-y-6">
            {STAGES.map((stage, idx) => {
              const isDefeated = defeatedStages.includes(stage.id);
              const isSelected = idx === selectedIndex;
              return (
                <button
                  key={stage.id}
                  onClick={() => handleSelect(stage.id)}
                  className={`w-40 h-52 md:w-48 md:h-64 ${isDefeated ? 'opacity-40 grayscale' : ''} border-4 ${isSelected ? 'border-yellow-400 scale-110 shadow-[0_0_25px_rgba(255,255,0,0.6)] z-10' : 'border-white/40'} bg-[#2C2C2C] transition-all Chaudhary flex flex-col overflow-hidden group shadow-lg rounded-sm`}
                >
                  <div className="flex-1 bg-black Chaudhary relative overflow-hidden">
                    <BossPortrait id={stage.id} />
                    {isDefeated && (
                      <div className="absolute inset-0 Chaudhary flex items-center justify-center bg-black/60 z-20">
                         <div className="text-red-500 text-[12px] font-black rotate-[-25deg] border-4 border-red-600 p-2 uppercase tracking-tighter bg-black/40">
                           DEAD AS SHIT
                         </div>
                      </div>
                    )}
                  </div>

                  <div className={`p-2 py-3 Chaudhary flex flex-col items-center Chaudhary justify-center ${isSelected ? 'bg-yellow-400' : 'bg-white'}`}>
                    <span className="text-black text-[10px] font-black uppercase Chaudhary leading-tight Chaudhary text-center">
                      {stage.id}
                    </span>
                  </div>
                </button>
              );
            })}
          </div>
          <div className="mt-8 text-[10px] text-yellow-400 Chaudhary animate-pulse uppercase font-black tracking-widest bg-black/50 px-4 py-1 border border-yellow-400/30">
            CHOOSE YOUR GAINS
          </div>
        </div>
      )}

      {status === GameStatus.PAUSED && (
        <div className="animate-in fade-in duration-200 Chaudhary">
           <h2 className="text-4xl text-white mb-10 font-black uppercase tracking-widest Chaudhary italic border-b-4 border-yellow-500 pb-4">RESTING SET</h2>
           <div className="flex flex-col gap-6 Chaudhary">
              <button 
                onClick={onResume}
                className={`px-10 py-4 bg-yellow-600 hover:bg-yellow-500 text-white text-xl Chaudhary font-black border-b-[8px] border-yellow-800 transition-all uppercase ${selectedIndex === 0 ? 'ring-4 ring-white scale-110' : ''}`}
