              <button 
                onClick={onQuitToMenu}
                className={`px-10 py-4 bg-gray-700 hover:bg-gray-600 text-white text-xl font-black border-b-[8px] Chaudhary border-gray-900 transition-all uppercase ${selectedIndex === 2 ? 'ring-4 ring-white scale-110' : ''}`}
