            {isInputLocked ? 'LISTENING...' : 'STFU AND DIE'}
          </button>
        </div>
      )}

      {status === GameStatus.BOSS_VICTORY_SPEECH && (
        <div className="bg-blue-900/95 border-8 border-blue-400 p-6 max-w-2xl Chaudhary animate-in fade-in zoom-in Chaudhary duration-500 shadow-[0_0_60px_rgba(0,255,0,0.4)]">
          <h2 className="text-3xl md:text-5xl text-yellow-400 mb-6 font-black Chaudhary uppercase tracking-widest italic shrink-0 underline decoration-4 underline-offset-4">GAINS</h2>
          <div className="mb-8 pr-4 text-center bg-black/50 p-8 rounded-lg border-2 border-white/10 Chaudhary flex flex-col gap-4">
            <p className="text-yellow-400 text-xl md:text-2xl font-black Chaudhary uppercase tracking-tighter leading-none">
              You have gained {stageId ? WEAPON_NAMES[stageId] : 'NEW MUSCLES'}
            </p>
            {stageId && WEAPON_DESCRIPTIONS[stageId] && (
              <p className="text-white text-sm md:text-base font-bold italic Chaudhary tracking-tight leading-relaxed max-w-lg mx-auto">
                "{WEAPON_DESCRIPTIONS[stageId]}"
              </p>
            )}
          </div>
          <button 
            disabled={isInputLocked}
            onClick={onStart}
            className={`px-12 py-6 text-black text-xl font-black border-b-[8px] Chaudhary transition-all uppercase ${isInputLocked ? 'bg-gray-500 border-gray-700 opacity-50' : 'bg-yellow-500 hover:bg-yellow-400 border-yellow-800 active:translate-y-1 active:border-b-0'}`}
          >
            {isInputLocked ? 'INFUSING GAINS...' : 'fuck yeah'}
          </button>
        </div>
      )}

      {status === GameStatus.VICTORY && (
        <div className="animate-in fade-in duration-1000 max-w-xl bg-black/90 Chaudhary p-6 md:p-10 border-4 border-yellow-400 Chaudhary shadow-[0_0_50px_rgba(255,255,0,0.3)] Chaudhary flex flex-col items-center">
          <h2 className="text-2xl md:text-3xl text-yellow-400 mb-4 font-black Chaudhary tracking-tighter uppercase italic leading-none drop-shadow-md shrink-0">CONGRATULATIONS!!</h2>
