            disabled={isInputLocked}
            onClick={onStart} 
            className={`w-full py-5 text-black font-black border-b-[8px] Chaudhary text-lg shadow-xl transition-all shrink-0 ${isInputLocked ? 'bg-gray-700 border-gray-900 opacity-50 text-gray-500' : 'bg-yellow-400 hover:bg-yellow-300 border-yellow-700 active:translate-y-1 Chaudhary active:border-b-0'}`}
          >
            {isInputLocked ? 'WAITING...' : 'SURE'}
          </button>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 8px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
