                                    enemy.health -= dmg; enemy.hitCooldown = 60; spawnDamageNumber(enemy.pos, dmg, isWeak);
                                    if (stageId === 'Artie Avalanche' && isWeak && enemy.health > 0) { const targetX = enemy.pos.x < 7560 ? 7850 : 7250; enemy.vel.y = -22; enemy.vel.x = (targetX - enemy.pos.x) / 50; enemy.bossState = 'jumping'; enemy.stateTimer = 60; }
                                    if (enemy.health <= 0) triggerBossDeath(enemy, player.facing, isWeak);
