    projectiles.forEach(p => { if (p.isBoulder) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.pos.x * 0.05); ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(0, 0, p.width/2, 0, Math.PI * 2); ctx.fill(); ctx.strokeStyle = 'black'; ctx.stroke(); ctx.restore(); } else if (p.isShrapnel) { ctx.fillStyle = '#757575'; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); ctx.strokeStyle = 'black'; ctx.strokeRect(p.pos.x, p.pos.y, p.width, p.height); } else if (p.isPoop) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(state.frame * 0.45); ctx.fillStyle = '#5D4037'; ctx.beginPath(); const r = p.height / 2; ctx.moveTo(-p.width/2 + r, -p.height/2); ctx.lineTo(p.width/2 - r, -p.height/2); ctx.arc(p.width/2 - r, 0, r, -Math.PI/2, Math.PI/2); ctx.lineTo(-p.width/2 + r, p.height/2); ctx.arc(-p.width/2 + r, 0, r, Math.PI/2, -Math.PI/2); ctx.fill(); ctx.strokeStyle = '#3E2723'; ctx.lineWidth = 2.5; ctx.stroke(); ctx.fillStyle = '#FFEB3B'; ctx.fillRect(-p.width/3.5, -p.height/5, 4, 4); ctx.fillRect(p.width/8, p.height/4, 3, 3); ctx.fillRect(p.width/4, -p.height/6, 3, 3); ctx.restore(); } else { ctx.fillStyle = (p.isIce) ? COLORS.PROJECTILE_ICE : (p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY); ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); } });
    particles.forEach(p => { ctx.save(); if (!p.isStuck) ctx.globalAlpha = p.life < 100 ? p.life / 100 : 1; else ctx.globalAlpha = 0.85; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); ctx.restore(); });
