  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    const stageWidth = 8000; const doorX = BOSS_DOOR_X;
    state.arenaLocked = false;
    state.doorState = 'closed';
    state.doorOpenAmount = 0;
    state.bossVolcanoes = [];
    state.bossVolcanoTelegraphs = [];
    state.bossPoopTelegraphs = [];
    state.bossSteamExplosions = [];
    state.victorWallSide = 0;
    state.ernieVibrationTimer = 0;
    state.playerStunTimer = 0;
    state.tsunamiActive = false;

    const addPickupOnPlatform = (block: { x: number, y: number, w: number, h: number }) => {
        const type: PickupType = Math.random() > 0.5 ? 'small_health' : 'small_ammo';
        state.pickups.push({
            id: `static-pickup-${Date.now()}-${Math.random()}`,
            pos: { x: block.x + block.w / 2 - 10, y: block.y - 25 },
            vel: { x: 0, y: 0 },
            width: 20,
            height: 20,
            type,
            life: 20000 
        });
    };

    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: stageWidth, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: -200, w: stageWidth, h: 200, type: 'wall' },     
      { x: 0, y: 550, w: stageWidth, h: 50, type: 'ground' },
      { x: doorX, y: 400, w: DOOR_WIDTH, h: 150, type: 'door' },
      { x: doorX, y: -1000, w: DOOR_WIDTH, h: 1400, type: 'wall' },
      { x: doorX, y: 0, w: stageWidth - doorX, h: 100, type: 'wall' },
      { x: 7960, y: 100, w: 40, h: 500, type: 'wall' }
    ];

    if (stageId === 'Artie Avalanche') {
        for (let i = 500; i < doorX; i += 700) {
            const p1 = { x: i, y: 450, w: 150, h: 20, type: 'platform' };
            const p2 = { x: i + 200, y: 320, w: 150, h: 20, type: 'platform' };
            const p3 = { x: i + 400, y: 190, w: 150, h: 20, type: 'platform' };
            state.blocks.push(p1, p2, p3);
            if (Math.random() > 0.4) addPickupOnPlatform(p2);
            if (Math.random() > 0.6) addPickupOnPlatform(p3);
        }
    } else if (stageId === 'Victor Volcano') {
        for (let i = 400; i < doorX; i += 800) {
            const p1 = { x: i, y: 380, w: 300, h: 20, type: 'platform' };
            const p2 = { x: i + 400, y: 250, w: 200, h: 20, type: 'platform' };
            state.blocks.push(p1, p2);
            if (Math.random() > 0.3) addPickupOnPlatform(p1);
            if (Math.random() > 0.3) addPickupOnPlatform(p2);
        }
        for (let x = 1200; x < doorX; x += 1800) { state.blocks.push({ x: x, y: 550, w: 400, h: 1000, type: 'pit' }); }
    } else {
        for (let i = 600; i < doorX; i += 600) { 
            const p = { x: i, y: 400 - (Math.random()*200), w: 200, h: 25, type: 'platform' };
            state.blocks.push(p); 
            if (Math.random() > 0.4) addPickupOnPlatform(p);
        }
    }
    state.enemies = [];
    if (!jumpToBossEnabled) {
      for (let i = 1200; i < doorX - 300; i += 1000) {
        state.enemies.push({ id: `shield-${i}`, pos: { x: i, y: 480 }, vel: { x: 0, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 0, initialX: i, shootTimer: 0, isShieldActive: true });
        state.enemies.push({ id: `flyer-${i}`, pos: { x: i + 400, y: 150 }, vel: { x: 2, y: 0 }, width: 40, height: 30, health: 40, maxHealth: 40, type: 'enemy', enemyType: 'flyer', behavior: 'fly', patrolRange: 300, initialX: i + 400, shootTimer: 0 });
        state.enemies.push({ id: `heavy-flyer-${i}`, pos: { x: i + 600, y: 100 }, vel: { x: 0, y: 0 }, width: 80, height: 65, health: 300, maxHealth: 300, type: 'enemy', enemyType: 'flyer', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0 });
        state.enemies.push({ id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0 });
        state.enemies.push({ id: `rusher-${i}`, pos: { x: i + 800, y: 480 }, vel: { x: 0, y: 0 }, width: 50, height: 70, health: 300, maxHealth: 300, type: 'enemy', enemyType: 'tank', behavior: 'patrol', patrolRange: 0, initialX: i + 800, shootTimer: 0, pauseTimer: 0 });
      }
    }
    state.enemies.push({ id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 666, maxHealth: 666, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0, bossState: 'idle', stateTimer: 60 });
  }, [stageId, jumpToBossEnabled]);

  const respawn = useCallback(() => {
    const state = gameStateRef.current;
    state.player.health = INITIAL_PLAYER_HEALTH; 
    const baseStartX = jumpToBossEnabled ? BOSS_DOOR_X - 800 : 0;
    state.player.pos = { x: baseStartX + 150, y: 100 }; 
    state.player.vel = { x: 0, y: 0 }; 
    state.player.invincibilityTimer = 0; 
    state.player.facing = 1; 
    state.player.isCharging = false;
    state.player.isUppercutting = false;
    state.player.currentWeapon = 'GUN';
    state.player.killSatisfactionTimer = 0;
    state.player.bossKillSatisfactionTimer = 0;
    state.player.pushbackTimer = 0;
    state.shouldSyncWeapon = true; 
    state.player.weaponAmmo = {
        'GUN': Infinity,
        'BOULDER': MAX_AMMO['BOULDER'],
        'SHOTGUN': MAX_AMMO['SHOTGUN'],
        'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'],
        'TSUNAMI': MAX_AMMO['TSUNAMI']
    };
    state.deathTimer = 0;
    state.deathString = "";
    state.victoryString = "";
    state.postVictoryTimer = 0;
    state.bossExplosionTimer = 0;
    state.frame = 1; 
    state.arenaLocked = false;
    state.tsunamiActive = false;
    state.doorState = 'closed';
    state.doorOpenAmount = 0;
    state.bossVolcanoes = [];
    state.bossVolcanoTelegraphs = [];
    state.bossPoopTelegraphs = [];
    state.bossSteamExplosions = [];
    state.bossTsunamiSide = 0;
    state.victorWallSide = 0;
    state.ernieVibrationTimer = 0;
    state.playerStunTimer = 0;
    state.screenShakeTimer = 0;
    state.playerLastVulgarity = "";
    state.playerVulgarityTimer = 0;
    state.bossLastVulgarity = "";
    state.bossVulgarityTimer = 0;
    state.particles = [];
    state.projectiles = [];
    state.pickups = [];
    state.damageNumbers = [];
    createLevel();
  }, [createLevel, jumpToBossEnabled]);

  const checkIsWeakness = (p?: Partial<Projectile>) => {
    if (!p) {
        if (stageId === 'Artie Avalanche' && currentWeapon === 'FLAMETHROWER') return true;
        if (stageId === 'Victor Volcano' && currentWeapon === 'TSUNAMI') return true;
        if (stageId === 'Ernie Earthquake' && currentWeapon === 'SHOTGUN') return true;
        if (stageId === 'Hector Hurricane' && currentWeapon === 'BOULDER') return true;
        return false;
    }
    if (stageId === 'Hector Hurricane' && p.isBoulder) return true;
    if (stageId === 'Victor Volcano' && p.isTsunami) return true;
    if (stageId === 'Artie Avalanche' && (p.owner === 'player' && currentWeapon === 'FLAMETHROWER')) return true;
    if (stageId === 'Ernie Earthquake' && p.isIce) return true;
    return false;
  };

  const getBossDamage = (boss: Enemy, p?: Partial<Projectile>) => {
    if (stageId === 'Victor Volcano' && (p?.isTsunami || (!p && currentWeapon === 'TSUNAMI'))) {
      return 150;
    }
    const isWeak = checkIsWeakness(p);
    return isWeak ? 100 : BULLET_DAMAGE;
  };

  const update = useCallback(() => {
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks, pickups, damageNumbers } = state;

    state.frame++;
    if (state.screenShakeTimer > 0) state.screenShakeTimer--;
    if (state.deathTimer > 0) {
        state.deathTimer--;
        if (state.deathTimer === 0) respawn();
        state.particles = state.particles.filter(p => { 
          if (!p.isStuck) { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; }
          return p.life > 0; 
        });
        return;
    }

    if (state.bossExplosionTimer > 0) {
      state.bossExplosionTimer--;
      if (state.frame % 3 === 0) {
        spawnDeathShower(state.bossExplosionPos, (Math.random() - 0.5) * 2, 5.0, true); 
      }
      state.particles = state.particles.filter(p => { 
          if (p.isStuck) return true;
          p.pos.x += p.vel.x; p.pos.y += p.vel.y; 
          if (p.isBossGore) {
            p.vel.y += 0.45; 
