        const damage = player.isUppercutting ? (enemy.type === 'boss' ? BOSS_UPPERCUT_DAMAGE : ENEMY_UPPERCUT_DAMAGE) : BOSS_CHARGE_DAMAGE;
        enemy.health -= damage; enemy.hitCooldown = 60; spawnDamageNumber(enemy.pos, damage, player.isUppercutting);
        if (enemy.health > 0) { 
          player.vel = { x: (player.pos.x + player.width/2 < enemy.pos.x + enemy.width/2 ? -1 : 1) * 18, y: -4 }; 
          player.pushbackTimer = 20; player.isCharging = false; player.isUppercutting = false; player.invincibilityTimer = 15; 
        } else {
            if (enemy.type === 'boss') triggerBossDeath(enemy, player.facing, false);
            else { enemy.isBlownAway = true; enemy.vel = { x: player.isUppercutting ? 0 : player.facing * 30, y: player.isUppercutting ? -30 : -5 }; spawnDeathShower(enemy.pos, player.facing); spawnPickup(enemy.pos); speakVulgarity(player.isUppercutting ? 'uppercut_kill' : 'charge_kill'); player.killSatisfactionTimer = 60; }
            return false;
        }
      } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x && player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y) {
          if (!invincibilityEnabled) player.health -= 7.5;
          if (player.health > 0) { player.invincibilityTimer = 60; speakVulgarity('hurt'); }
      }
      return true;
    });

    state.projectiles = projectiles.filter(p => {
      if (p.health <= 0) return false;
      p.pos.x += p.vel.x; p.pos.y += p.vel.y;
      if (p.owner === 'player') {
        for (const enemy of state.enemies) {
          if (enemy.health > 0 && !enemy.isBlownAway) {
            if (p.pos.x < enemy.pos.x + enemy.width && p.pos.x + p.width > enemy.pos.x && p.pos.y < enemy.pos.y + enemy.height && p.pos.y + p.height > enemy.pos.y) {
              if (enemy.type === 'boss') {
                if (enemy.hitCooldown && enemy.hitCooldown > 0) return false; 
                const dmg = getBossDamage(enemy, p), isWeak = checkIsWeakness(p); enemy.health -= dmg; enemy.hitCooldown = 60; spawnDamageNumber(enemy.pos, dmg, isWeak);
                if (enemy.health <= 0) triggerBossDeath(enemy, p.vel.x > 0 ? 1 : -1, isWeak);
              } else {
                enemy.health -= p.damage; spawnDamageNumber(enemy.pos, p.damage, p.isBoulder);
                if (enemy.health <= 0) { spawnDeathShower(enemy.pos, 0, 1.2); spawnPickup(enemy.pos); speakVulgarity(p.isBoulder ? 'boulder_kill' : 'gun_kill'); player.killSatisfactionTimer = 60; }
              }
              return false;
            }
          }
        }
      } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
          if (!invincibilityEnabled) player.health -= (p.damage / 2);
          if (player.health > 0) { player.invincibilityTimer = 60; speakVulgarity('hurt'); player.pushbackTimer = 20; }
          return false;
      }
      return p.pos.x > state.camera.x - 400 && p.pos.x < state.camera.x + CANVAS_WIDTH + 400;
    });

    state.pickups = pickups.filter(p => {
      p.vel.y += GRAVITY; p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.vel.x *= 0.9; p.life--;
      if (p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
        if (p.type.includes('health')) player.health = Math.min(player.maxHealth, player.health + (p.type === 'large_health' ? 50 : 20));
        else { const pct = p.type === 'large_ammo' ? AMMO_PICKUP_PCT.LARGE : AMMO_PICKUP_PCT.SMALL; let target = player.currentWeapon === 'GUN' ? 'BOULDER' : player.currentWeapon; if (target !== 'GUN') player.weaponAmmo[target] = Math.min(MAX_AMMO[target], player.weaponAmmo[target] + MAX_AMMO[target] * pct); }
        return false;
      }
      return p.life > 0;
    });

    state.particles = state.particles.filter(p => { 
      if (!p.isStuck) { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; }
      return p.life > 0; 
    });

    state.damageNumbers = damageNumbers.filter(d => { d.pos.x += d.vel.x; d.pos.y += d.vel.y; d.vel.y += 0.15; d.life--; return d.life > 0; });
    if (!state.arenaLocked && state.victoryString === "") state.camera.x = Math.max(0, Math.min(8000 - CANVAS_WIDTH, player.pos.x - CANVAS_WIDTH / 2));
    if (player.health <= 0 || player.pos.y > 1000) { if (state.deathTimer <= 0) { state.deathTimer = 180; state.deathString = "YOU DIED"; spawnDeathShower(player.pos, player.facing, 3); speakVulgarity('death'); } }
    onPlayerUpdate(player.health, player.specialCharges, player.specialChargeTimer, player.weaponAmmo, state.shouldSyncWeapon ? 'GUN' : undefined);
    if (state.shouldSyncWeapon) state.shouldSyncWeapon = false;
  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onBossDeath, onGameOver, onIntroComplete, onBossTransition, currentWeapon, respawn, invincibilityEnabled, infiniteAmmoEnabled, infinitePowerEnabled, jumpToBossEnabled]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    if (gameStateRef.current.deathTimer > 0) return;
    ctx.save(); let drawX = p.pos.x, drawY = p.pos.y, drawW = p.width, drawH = p.height;
    if (p.isDucking) { drawY += 28; drawH -= 28; }
    if (p.isUppercutting) { drawH += 30; drawY -= 30; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 5, drawY - 5, drawW + 10, drawH + 10); ctx.globalAlpha = 1.0; } 
    else if (p.isCharging) { drawW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0; }
    const isFlashing = (p.invincibilityTimer > 0 || invincibilityEnabled) && Math.floor(gameStateRef.current.frame / 5) % 2 === 0;
    if (!isFlashing) { ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6); ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4); }
    ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current; if (!canvas) return; const ctx = canvas.getContext('2d'); if (!ctx) return; const state = gameStateRef.current;
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) { ctx.fillStyle = 'black'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT); return; }
    const { player, enemies, projectiles, particles, blocks, camera, pickups, damageNumbers } = state;
    const colors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };
    ctx.fillStyle = colors.bg; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save(); if (state.screenShakeTimer > 0) ctx.translate((Math.random()-0.5)*15, (Math.random()-0.5)*15);
    ctx.translate(-camera.x, -camera.y);
    blocks.forEach(b => { if (b.type === 'door') ctx.fillStyle = '#555'; else if (b.type === 'pit') ctx.fillStyle = '#f00'; else { ctx.fillStyle = colors.ground; ctx.strokeStyle = colors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); } ctx.fillRect(b.x, b.type === 'door' ? b.y - state.doorOpenAmount : b.y, b.w, b.h); });
    pickups.forEach(p => { ctx.fillStyle = p.type.includes('health') ? 'red' : 'yellow'; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    enemies.forEach(e => { if (e.health <= 0 && !e.isBlownAway) return; ctx.fillStyle = e.type === 'boss' ? 'purple' : 'red'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); });
    drawPlayer(ctx, player);
    projectiles.forEach(p => { ctx.fillStyle = p.owner === 'player' ? 'yellow' : 'white'; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    particles.forEach(p => { ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    damageNumbers.forEach(d => { ctx.fillStyle = 'white'; ctx.fillText(d.value.toString(), d.pos.x, d.pos.y); });
    ctx.restore();
  }, [status, stageId]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    frameId = window.requestAnimationFrame(loop);
    return () => window.cancelAnimationFrame(frameId);
  }, [update, draw]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

