                  const forceDir = (e.pos.x + e.width/2 - (player.pos.x + player.width/2)) > 0 ? 1 : -1;
                  player.vel.x += forceDir * HECTOR_PULL_STRENGTH;
                  if (Math.abs((e.pos.x + e.width/2) - (player.pos.x + player.width/2)) < 300 && player.invincibilityTimer <= 0 && !invincibilityEnabled) {
                    player.health -= 4; if (player.health > 0) { player.invincibilityTimer = 25; player.pushbackTimer = 2; speakVulgarity('hurt'); }
