        else { player.isCharging = true; player.vel.x = player.facing * (player.isGrounded ? CHARGE_SPEED : AIR_CHARGE_SPEED); }
      }

      if (shootRequested && player.shootCooldown <= 0 && (currentWeapon === 'GUN' || player.weaponAmmo[currentWeapon] >= 1)) {
