          else if (enemy.behavior === 'shoot' && onScreen) {
              enemy.shootTimer++; if (enemy.shootTimer > 60) { projectiles.push({ id: `ep-${Date.now()}`, pos: { x: enemy.pos.x + enemy.width/2, y: enemy.pos.y + 10 }, vel: { x: player.pos.x < enemy.pos.x ? -7 : 7, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy' }); enemy.shootTimer = 0; }
          }
