            if (enemy.type === 'boss') triggerBossDeath(enemy, player.facing, false);
            else { enemy.isBlownAway = true; enemy.vel = { x: player.isUppercutting ? 0 : player.facing * 30, y: player.isUppercutting ? -30 : -5 }; spawnDeathShower(enemy.pos, player.facing); spawnPickup(enemy.pos); speakVulgarity(player.isUppercutting ? 'uppercut_kill' : 'charge_kill'); player.killSatisfactionTimer = 60; }
            return false;
        }
      } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && player.pos.x < enemy.pos.x + enemy.width && player.pos.x + player.width > enemy.pos.x && player.pos.y < enemy.pos.y + enemy.height && player.pos.y + player.height > enemy.pos.y) {
          if (!invincibilityEnabled) player.health -= 7.5;
          if (player.health > 0) { player.invincibilityTimer = 60; speakVulgarity('hurt'); }
