  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player) => {
    if (gameStateRef.current.deathTimer > 0) return;
    ctx.save(); let drawX = p.pos.x, drawY = p.pos.y, drawW = p.width, drawH = p.height;
    if (p.isDucking) { drawY += 28; drawH -= 28; }
    if (p.isUppercutting) { drawH += 30; drawY -= 30; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 5, drawY - 5, drawW + 10, drawH + 10); ctx.globalAlpha = 1.0; } 
    else if (p.isCharging) { drawW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(drawX - 10, drawY - 5, drawW + 20, drawH + 10); ctx.globalAlpha = 1.0; }
    const isFlashing = (p.invincibilityTimer > 0 || invincibilityEnabled) && Math.floor(gameStateRef.current.frame / 5) % 2 === 0;
    if (!isFlashing) { ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(drawX, drawY, drawW, drawH * 0.6); ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(drawX, drawY + drawH * 0.6, drawW, drawH * 0.4); }
