                    e.vel.y = -12; e.vel.x = (player.pos.x - e.pos.x) * 0.03; e.stateTimer = 180; 
                    projectiles.push({ 
                        id: `b-ernie-jump-${Date.now()}`, pos: { x: e.pos.x + e.width/2, y: e.pos.y + 20 }, vel: { x: dirToPlayer * (BOULDER_SPEED + 1), y: 0 }, 
                        width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isBoulder: true 
                    });
                }
            }
