                    if (prevY < 470 && e.vel.y > 0 && stageId === 'Ernie Earthquake') {
                        state.screenShakeTimer = 30; state.ernieVibrationTimer = 40; 
                        projectiles.push({ 
                            id: `b-ernie-land-${Date.now()}`, pos: { x: e.pos.x + e.width/2, y: e.pos.y + 20 }, vel: { x: dirToPlayer * (BOULDER_SPEED + 1), y: 0 }, 
                            width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isBoulder: true 
                        });
                    }
                    e.vel.y = 0; e.vel.x = 0; e.isGroundedBoss = true;
                } else e.isGroundedBoss = false;
            } else {
                e.vel.y += GRAVITY * 1.5; e.pos.y += e.vel.y;
                if (e.pos.y > 470) { e.pos.y = 470; e.vel.y = 0; e.isGroundedBoss = true; if (e.stateTimer > 30) e.stateTimer = 30; }
            }
        }
    });

    player.isDucking = moveDown && player.isGrounded && !player.isCharging && !player.isUppercutting;

    if (player.jumpPrepTimer > 0) {
